window.VI_TRANSLATIONS_A = {"1":{"q":"Pipeline của bạn review mỗi PR bằng một lệnh gọi API duy nhất với một prompt tĩnh chứa diff và toàn bộ nội dung của từng file đã thay đổi — các file không thay đổi không được đưa vào. Các review được đăng bất đồng bộ (asynchronously) và không chặn việc tạo PR. Các developer báo cáo rằng review liên tục bỏ sót các bug liên quan đến tương tác cross-file — ví dụ, một PR đổi tên các tham số của một hàm nhưng review không gắn cờ (flag) các lời gọi (caller) trong các file không thay đổi vẫn còn sử dụng thứ tự tham số cũ. Đánh giá (evaluation) cho thấy các bug cross-file chiếm 35% số sự cố production từ các PR đã được review. Thay đổi hiệu quả nhất đối với thiết kế review của bạn là gì?","e":"Lỗi ở đây là một vấn đề thiếu context: các caller nằm trong những file không thay đổi mà prompt tĩnh không bao giờ đưa vào, vì vậy chain-of-thought (B) không thể giúp model suy luận về code mà nó không nhìn thấy được, còn các heuristic tĩnh (C, D) làm phình to context trong khi vẫn bỏ sót các tham chiếu động hoặc đa bước (multi-hop). Hướng dẫn của Anthropic về agent ủng hộ agentic search — để model tự truy xuất chính xác context mà nó cần thông qua các tool đọc file/tìm kiếm (file-read/search tools) — và pipeline review bất đồng bộ, không chặn (nonblocking) có thể chấp nhận độ trễ tăng thêm, trong khi một giới hạn turn (turn limit) sẽ giới hạn chi phí.","o":{"A":"Thiết kế lại việc review thành một agentic task có giới hạn số turn, trong đó model có thể đọc file và tìm kiếm trong codebase thông qua tool, đi theo các reference để xác minh các phát hiện liên quan đến nhiều file.","B":"Thêm chain-of-thought instructions yêu cầu model liệt kê tất cả các external reference trong diff, sau đó suy luận từng bước (step-by-step) về việc mỗi thay đổi có thể ảnh hưởng đến các caller ở file khác như thế nào.","C":"Chạy song song các lượt review theo từng file đã thay đổi, kèm theo các dependent trực tiếp trong mỗi lượt, sau đó tổng hợp và loại bỏ trùng lặp các phát hiện bằng một lời gọi summarization cuối cùng.","D":"Dùng static analysis để xây dựng dependency graph của phần code đã thay đổi, sau đó mở rộng prompt để bao gồm tất cả các file nằm trong phạm vi hai bước dependency (two dependency hops) tính từ bất kỳ file đã thay đổi nào."}},"2":{"q":"Một engineer yêu cầu agent của bạn thêm các test toàn diện cho một codebase legacy gồm 200 file với độ bao phủ test (test coverage) hiện có rất ít. Engineer này không chỉ định module nào cần ưu tiên. Agent nên phân rã (decompose) tác vụ mở (open-ended task) này như thế nào?","e":"Các best practice về agent của Anthropic ủng hộ việc thu thập context hiệu quả bằng các search tool (Glob/Grep) thay vì đọc toàn bộ từng file một cách tận, điều này sẽ lãng phí context và thời gian. Ưu tiên các module có tác động lớn (high-impact), liên kết chặt chẽ (heavily-coupled) và điều chỉnh kế hoạch lặp lại (iteratively) khi các dependency xuất hiện là cách đúng để phân rã một tác vụ mở; A lãng phí, B bỏ qua tác động/độ phức tạp, và C tùy tiện và không có kế hoạch.","o":{"A":"Đọc một cách có hệ thống toàn bộ 200 file để tạo một bảng kiểm kê function đầy đủ trước khi viết bất kỳ test nào, đảm bảo kế hoạch testing bao quát mọi function trước khi bắt đầu.","B":"Tạo trước một lịch trình testing cố định dựa trên cấu trúc thư mục, phân bổ nỗ lực đều nhau cho mỗi thư mục cấp cao nhất bất kể độ phức tạp của code hay tầm quan trọng đối với business.","C":"Bắt đầu viết test cho module đầu tiên theo thứ tự bảng chữ cái, dùng các test failure và import để phát hiện các file liên quan một cách tự nhiên.","D":"Dùng Glob và Grep để lập bản đồ cấu trúc codebase, xác định các module có mức độ liên kết chặt (heavily-coupled), tạo một kế hoạch ưu tiên cho các khu vực có tác động cao (high-impact), và điều chỉnh khi phát hiện thêm các dependency."}},"3":{"q":"Một engineer gửi hai yêu cầu: Yêu cầu A: \"Đổi tên hàm getUserData thành fetchUserProfile ở mọi nơi nó được sử dụng.\" Yêu cầu B: \"Cải thiện việc xử lý lỗi (error handling) trong toàn bộ module xử lý dữ liệu — thêm các khối try/catch, các thông báo lỗi có ý nghĩa, và đảm bảo các lỗi (failure) không âm thầm làm hỏng dữ liệu.\" Đối với yêu cầu nào thì việc chỉ định rõ một workflow nhiều giai đoạn (multi-phase workflow) (chẳng hạn analyze → propose → implement with review) cải thiện chất lượng kết quả nhiều nhất?","e":"Yêu cầu B là mở (open-ended) và đòi hỏi nhiều phán đoán (judgment-heavy) — \"cải thiện việc xử lý lỗi\" đòi hỏi phải phân tích hành vi hiện tại, quyết định try/catch nên đặt ở đâu, và chọn các thông báo có ý nghĩa, vì vậy một workflow rõ ràng analyze → propose → implement-with-review sẽ nâng cao chất lượng đáng kể và phát hiện thiết kế sai trước khi thay đổi code. Yêu cầu A là một thao tác đổi tên (rename) máy móc, được định nghĩa rõ ràng mà một cách thực thi kiểu find-and-replace đơn giản đã xử lý tốt, vì vậy cấu trúc nhiều giai đoạn (multi-phase) không mang lại nhiều giá trị thêm.","o":{"A":"Yêu cầu B, task xử lý lỗi (error handling)","B":"Cả hai yêu cầu đều được hưởng lợi như nhau","C":"Yêu cầu A, task đổi tên function (function rename)","D":"Không yêu cầu nào được hưởng lợi đáng kể"}},"4":{"q":"Trợ lý review code của bạn cần phân tích các pull request và đưa ra phản hồi về ba khía cạnh: tuân thủ code style, các vấn đề bảo mật (security) tiềm ẩn, và mức độ đầy đủ của tài liệu (documentation). Mỗi khía cạnh đòi hỏi đọc file, chạy các analysis tool, và tạo ra một phần của báo cáo. Quy trình review tuân theo cùng một workflow ba bước cho mọi PR. Pattern phân rã tác vụ (task decomposition pattern) nào phù hợp nhất cho workflow này?","e":"Tình huống nói rõ rằng việc review \"tuân theo cùng một workflow ba bước cho mọi PR\", đây theo hướng dẫn \"Building Effective Agents\" của Anthropic chính là trường hợp kinh điển cho workflow prompt chaining: một chuỗi các subtask cố định, có thể dự đoán được, mỗi subtask được xử lý bởi một prompt tập trung (focused), sau đó được tổng hợp lại. Orchestrator-workers (D) chỉ phù hợp khi các subtask cần thiết thay đổi không thể dự đoán tùy theo từng input, còn routing (B) áp dụng khi các input rơi vào các danh mục (category) khác biệt cần cách xử lý khác nhau — không cái nào phù hợp với một workflow cố định, giống hệt nhau.","o":{"A":"Một prompt toàn diện duy nhất (single comprehensive prompt) — đưa tất cả instructions vào một prompt và để model tự xử lý cả ba khía cạnh cùng lúc.","B":"Routing — phân loại mỗi PR theo loại (feature, bugfix, refactor) trước, sau đó định tuyến đến các review prompt khác nhau được tối ưu cho từng loại đó.","C":"Prompt chaining — chia việc review thành các bước tuần tự, trong đó mỗi khía cạnh (style, security, documentation) được phân tích riêng biệt, với các output được kết hợp ở bước tổng hợp (synthesis) cuối cùng.","D":"Orchestrator-workers — để một LLM trung tâm phân tích mỗi PR nhằm xác định động (dynamically) những kiểm tra nào là cần thiết, sau đó ủy quyền (delegate) cho các worker LLM chuyên biệt cho từng subtask đã xác định."}},"5":{"q":"Pipeline nghiên cứu multi-agent của bạn bị crash sau khi xử lý được 12 trong số 28 tài liệu. Agent web search đã xác định được các nguồn liên quan, document analyzer đã hoàn thành một phần việc extraction, và synthesizer đã bắt đầu việc xác định pattern. Bạn cần tiếp tục xử lý mà không lặp lại công việc đã làm hay mất đi độ chính xác (fidelity) của các phát hiện trước đó. Cách tiếp cận quản lý state (state management) nào cân bằng tốt nhất giữa độ chính xác thông tin (information fidelity) và hiệu quả sử dụng context khi khôi phục (restore) trạng thái agent?","e":"Các best practice về multi-agent của Anthropic khuyến nghị lưu trữ bền vững (persist) các artifact có cấu trúc (structured artifact) vào external storage và để orchestrator chọn lọc chỉ đưa (re-inject) lại phần state liên quan vào context của mỗi subagent. Cách này bảo toàn được độ chính xác (các bản export có cấu trúc không mất mát dữ liệu — lossless — cùng với một manifest ghi lại công việc đã hoàn thành) trong khi vẫn hiệu quả về context, trong khi A thiếu logic resume có phối hợp, B làm ngập (flood) agent với toàn bộ conversation log, và semantic search của C có tính lossy và có thể bỏ sót hoặc làm sai lệch các phát hiện trước đó.","o":{"A":"Để mỗi agent duy trì file trạng thái (state file) riêng của nó và tự tải lại một cách độc lập vào đầu mỗi session.","B":"Lưu lại (persist) log hội thoại của coordinator chứa toàn bộ các lượt ủy quyền task (task delegation) và phản hồi, rồi cung cấp lại cho các agent khi resume.","C":"Lập chỉ mục toàn bộ output của agent vào một shared vector store. Khi resume, mỗi agent truy vấn store này bằng semantic search để lấy lại các phát hiện trước đó có liên quan.","D":"Để mỗi agent lưu lại một bản export có cấu trúc (structured export) vào một vị trí đã biết. Khi resume, coordinator tải manifest và đưa (inject) trạng thái liên quan vào prompt của agent."}},"6":{"q":"Tình huống: Multi-Agent Research — Giám sát production (production monitoring) cho thấy giai đoạn nghiên cứu (research phase) mất nhiều thời gian hơn dự kiến. Phân tích cho thấy coordinator gọi subagent web search, chờ phản hồi của nó, sau đó gọi subagent document analysis và lại chờ tiếp. Hai tác vụ này độc lập với nhau — không tác vụ nào cần output của tác vụ kia. Bạn nên sửa đổi hệ thống như thế nào để chạy các subagent này đồng thời (concurrently)?","e":"Trong kiến trúc agent của Claude, các subagent chạy đồng thời khi coordinator phát ra nhiều lệnh gọi Task tool trong cùng một assistant message — harness sẽ thực thi song song các block tool_use trong cùng một turn. Phương án A chỉ tăng tốc từng bước tuần tự (serial), B thêm hạ tầng bên ngoài không cần thiết, lặp lại những gì agent loop đã hỗ trợ sẵn, còn D chỉ giải thích/yêu cầu tính song song mà không đảm bảo cơ chế cấu trúc (structural mechanism) (các lệnh gọi tool trong cùng một message) thực sự tạo ra việc thực thi đồng thời.","o":{"A":"Chuyển cả hai subagent sang dùng model tier Haiku thay vì Sonnet để giảm thời gian thực thi riêng của từng subagent.","B":"Tạo một lớp orchestration bất đồng bộ (async) bên ngoài agent, lớp này sinh ra các thread song song, mỗi thread chạy một cặp coordinator-subagent riêng biệt, rồi tổng hợp kết quả.","C":"Cấu trúc coordinator để phát ra cả hai lời gọi Task tool (cho web search và document analysis) trong cùng một tin nhắn phản hồi, thay vì ở các turn hội thoại riêng biệt.","D":"Thêm instructions chi tiết vào system prompt của coordinator giải thích lợi ích về hiệu năng của việc thực thi song song và yêu cầu nó gọi cả hai subagent cùng một lúc."}},"7":{"q":"Coordinator agent có AgentDefinitions được cấu hình cho cả bốn subagent chuyên biệt, mỗi cái có description, prompt và giới hạn tool (tool restriction) phù hợp. Trong quá trình testing, bạn nhận thấy coordinator suy luận đúng về thời điểm cần delegate (ủy quyền) — nó tạo ra các message như \"Tôi sẽ nhờ web search agent tìm nguồn về chủ đề này\" — nhưng không có subagent nào thực sự được thực thi. Coordinator sau đó tiếp tục như thể việc delegate đã xảy ra và làm việc với thông tin không đầy đủ. Log không cho thấy lỗi nào. Nguyên nhân khả dĩ nhất là gì?","e":"Trong Claude Agent SDK, các subagent được định nghĩa qua AgentDefinitions được khởi chạy thông qua Task tool; nếu allowedTools bỏ sót \"Task\", coordinator vẫn có thể suy luận bằng lời về việc delegate nhưng không có cơ chế nào để thực sự spawn (khởi tạo) subagent, và nó âm thầm tiếp tục mà không có chúng — khớp với triệu chứng không có thực thi và không có lỗi. max_tokens bị cắt ngắn (truncated) (C) hoặc thiếu liệt kê prompt (A) sẽ tạo ra lỗi hoặc hành vi khác, và context isolation (B) không ngăn cản việc invocation (gọi thực thi).","o":{"A":"Các AgentDefinition được cấu hình đúng, nhưng system prompt của coordinator không liệt kê rõ ràng các loại subagent khả dụng, khiến model không biết chúng có thể được gọi.","B":"Việc cô lập context của subagent (subagent context isolation) nghĩa là các mô tả task từ coordinator không tự động đến được subagent; bạn cần cấu hình việc chuyển tiếp context (context forwarding) rõ ràng trong ClaudeAgentOptions.","C":"Thiết lập max_tokens của coordinator quá thấp, khiến lời gọi Task tool bị cắt ngắn (truncated) trước khi tham số subagent type có thể được chỉ định.","D":"Cấu hình allowedTools của coordinator không bao gồm \"Task\", vì vậy dù nó có thể suy luận về việc ủy quyền (delegation), nó không thể gọi tool cần thiết để sinh ra các subagent."}},"8":{"q":"Tình huống: Multi-Agent Research — Khi phân tích các vụ án pháp lý (legal case) phức tạp có trích dẫn nhiều tiền lệ (precedent), subagent document analysis xử lý từng tiền lệ một cách tuần tự (sequentially). Một vụ án mang tính bước ngoặt (landmark case) trích dẫn 12 tiền lệ mất hơn 3 phút để phân tích xong hoàn toàn. Cách hiệu quả nhất để giảm độ trễ (latency) này trong khi vẫn giữ được khả năng giám sát (monitor) và debug hệ thống của coordinator là gì?","e":"Thiết kế multi-agent được Anthropic khuyến nghị là pattern orchestrator-worker với một hệ thống phân cấp phẳng (flat hierarchy): chính coordinator sẽ spawn các subagent song song và tổng hợp (aggregate) kết quả của chúng, điều này giảm latency nhờ tính song song trong khi vẫn giữ toàn bộ việc spawning, monitoring và debugging tập trung tại một nơi. Các phương án B và C tạo ra các hệ thống phân cấp agent lồng nhau/đệ quy (nested/recursive) làm suy giảm nghiêm trọng khả năng quan sát (observability) và khả năng debug, còn D đưa vào hạ tầng hàng đợi bất đồng bộ (asynchronous queue) làm tách rời công việc khỏi tầm nhìn trực tiếp (direct visibility) của coordinator.","o":{"A":"Để coordinator sinh ra các subagent phân tích tài liệu (document analysis) chạy song song, mỗi subagent xử lý một tập con các precedent, sau đó tổng hợp kết quả trước khi synthesis.","B":"Cho phép subagent phân tích tài liệu tự sinh ra các subagent chuyên biệt của riêng nó một cách động (dynamically) khi gặp các case có nhiều citation.","C":"Tạo một cấu trúc phân cấp agent đệ quy (recursive agent hierarchy), trong đó các agent phân tích chia nhỏ công việc cho các agent con cho đến khi đạt độ chi tiết từng precedent riêng lẻ.","D":"Triển khai một message queue trong đó các task phân tích precedent được xử lý bất đồng bộ (asynchronously) bởi một pool các worker agent."}},"9":{"q":"Tình huống: Multi-Agent Research — Trong production, các báo cáo cuối cùng thường xuyên chứa các luận điểm (claim) mà không có sự quy chiếu nguồn (source attribution) phù hợp. Điều tra cho thấy trong khi các agent web search và document analysis gắn trích dẫn (citation) đúng vào output của chúng, agent synthesis lại mất dấu việc nguồn nào hỗ trợ cho kết luận nào khi kết hợp các phát hiện lại với nhau. Thay đổi kiến trúc (architectural change) hiệu quả nhất là gì?","e":"Lỗi ở đây là sự mất thông tin (information loss) tại giai đoạn synthesis, vì vậy cách khắc phục là mang theo attribution (quy chiếu nguồn) dưới dạng structured data xuyên suốt (end-to-end): các subagent phát ra các ánh xạ claim-source (claim-source mapping) rõ ràng và agent synthesis bắt buộc phải bảo toàn và hợp nhất (merge) chúng. Điều này khớp với best practice của Anthropic về multi-agent là dùng structured output thay vì các quy ước tiền tố văn bản (text-prefix convention) mong manh (A), phân tích log sau sự việc (post-hoc log analysis) tốn kém (B), hoặc tái tạo bằng semantic-similarity không đáng tin cậy (D).","o":{"A":"Để coordinator chèn các tiền tố định danh nguồn (source identifier prefix) vào văn bản trước mỗi lần bàn giao (handoff), sau đó phân tích các tiền tố này khi tạo báo cáo để tái tạo lại citation.","B":"Duy trì bản ghi đầy đủ (complete transcript) của mọi tương tác giữa các subagent và thêm một agent giải quyết citation (citation-resolution agent) để phân tích log và xác định attribution trước khi tạo báo cáo.","C":"Yêu cầu tất cả subagent xuất ra các ánh xạ claim-source có cấu trúc (structured claim-source mapping) mà synthesis agent phải giữ nguyên và hợp nhất khi kết hợp các phát hiện từ nhiều nguồn.","D":"Thêm một bước xác minh trong đó report generator dùng semantic similarity matching so với các nguồn gốc để tái tạo lại claim nào đến từ tài liệu nào."}},"10":{"q":"Người dùng báo cáo rằng các báo cáo cuối cùng đôi khi thiếu chiều sâu ở một số chủ đề con (subtopic) cụ thể. Điều tra cho thấy agent document analysis thường xuyên phát hiện ra các khoảng trống (gap) — ví dụ, ghi chú rằng \"các nguồn thu thập được thảo luận về API authentication nhưng thiếu chi tiết về các pattern token refresh\" — nhưng theo pipeline nghiêm ngặt hiện tại, phát hiện này không thể hành động được (actionable) vì search đã hoàn tất. Thay đổi kiến trúc hiệu quả nhất là gì?","e":"Vấn đề cốt lõi là một pipeline một chiều (one-way), cứng nhắc, nơi các phát hiện về gap xuất hiện sau khi search đã kết thúc, vì vậy cách khắc phục là một vòng phản hồi khép kín (closed feedback loop): agent analysis đưa các gap cụ thể của nó ra dưới dạng structured output cho coordinator, coordinator này sẽ kích hoạt các lượt search bổ sung có mục tiêu (targeted follow-up search) và chạy lại việc phân tích một cách lặp lại (iteratively) cho đến khi mức độ bao phủ (coverage) đủ tốt. Điều này khớp với pattern agent orchestrator-worker của Anthropic là lặp lại cho đến khi đạt được một tiêu chí thành công có thể kiểm chứng (verifiable success criterion); phương án A là một vòng lặp một phần yếu hơn, còn B và C không làm cho phát hiện về gap trở nên actionable tại runtime.","o":{"A":"Để coordinator xem xét output phân tích để tìm các chỉ báo về khoảng trống (gap indicator) và gọi lại search với các query đã được thông tin bởi khoảng trống đó khi phát hiện gap.","B":"Để synthesis agent gắn điểm tin cậy (confidence score) cho mỗi phần và đánh dấu các khu vực có độ bao phủ chưa đủ để review thủ công.","C":"Thêm một agent lập kế hoạch nghiên cứu (research planning agent) trước giai đoạn search, agent này phân rã chủ đề thành các câu hỏi con cụ thể.","D":"Để agent phân tích báo cáo các gap cụ thể cho coordinator, việc này kích hoạt các lượt search có mục tiêu và gọi lại phân tích cho đến khi đủ."}},"11":{"q":"Tình huống: Multi-Agent Research System. Sau khi các subagent web search và document analysis hoàn thành tác vụ của chúng, coordinator cần spawn subagent synthesis để tổng hợp (synthesize) các phát hiện. Cách tiếp cận đúng để cung cấp cho subagent synthesis những thông tin nó cần là gì?","e":"Best practice về multi-agent của Anthropic là để các subagent lưu trữ (deposit) toàn bộ output của chúng dưới dạng artifact trong external/shared storage và truyền các tham chiếu (reference) nhẹ, để subagent synthesis đọc trực tiếp các kết quả trước đó thay vì nhận các bản sao lossy hoặc nặng token (token-heavy) qua prompt. Callback giữa các subagent (A) và context inheritance (kế thừa context) tự động (D) không tồn tại trong kiến trúc này, và việc chèn (inline) toàn bộ findings vào prompt (B) làm phình to context và có nguy cơ mất thông tin.","o":{"A":"Cung cấp cho subagent các định nghĩa tool cho phép nó yêu cầu output từ các subagent khác thông qua callback.","B":"Đưa toàn bộ phát hiện từ cả hai subagent trực tiếp vào prompt của synthesis subagent.","C":"Truyền các định danh tham chiếu (reference identifier) và cấu hình cho subagent quyền đọc vào một shared memory store nơi các subagent khác đã lưu kết quả của chúng.","D":"Sinh ra subagent chỉ với một mô tả task ngắn gọn, dựa vào việc kế thừa context tự động (automatic context inheritance) từ coordinator."}},"12":{"q":"Một người dùng đang mở rộng hệ thống nghiên cứu vượt ra ngoài agent web search đơn lẻ ban đầu bằng cách thêm các nguồn dữ liệu chuyên biệt. Họ thêm một agent financial API trả về JSON có cấu trúc với revenue, margin, và growth rate; một agent news monitoring trả về các bản tóm tắt dạng văn xuôi (prose) về các diễn biến gần đây; và một agent patent analysis trả về các danh sách có cấu trúc về các lĩnh vực công nghệ. Agent synthesis kết hợp những thứ này thành các bản tóm tắt điều hành (executive briefing). Hiện tại, nó chuyển đổi mọi thứ thành bullet point, khiến các so sánh tài chính mất đi sự rõ ràng dạng bảng (tabular clarity) và các bản tin tức mất đi mạch tường thuật (narrative flow). Thay đổi nào sẽ cải thiện chất lượng briefing nhiều nhất?","e":"Sự mất chất lượng đến từ việc làm phẳng (flatten) nội dung không đồng nhất (heterogeneous) thành một định dạng thống nhất duy nhất (bullet); các phương án A, C, và D chỉ lặp lại sai lầm đó với một cách biểu diễn thống nhất khác. Cách khắc phục tốt nhất là làm cho agent synthesis nhận biết định dạng (format-aware), trình bày mỗi loại nội dung theo hình thức tự nhiên của nó — bảng (table) cho các so sánh tài chính, văn xuôi (prose) cho các bản tường thuật tin tức — bảo toàn thế mạnh của output từng subagent.","o":{"A":"Thêm một lớp chuyển đổi định dạng (format conversion layer) giữa các subagent và synthesis, lớp này chuyển đổi tất cả output sang một biểu diễn trung gian chung (common intermediate representation).","B":"Cập nhật synthesis agent để hiển thị mỗi loại nội dung một cách phù hợp — dữ liệu tài chính dưới dạng bảng, tin tức dưới dạng văn xuôi.","C":"Chuẩn hóa tất cả output của subagent thành các bản tóm tắt văn xuôi (prose summary) kèm citation inline.","D":"Chuẩn hóa tất cả output của subagent thành JSON với các trường claim, evidence, source, và confidence."}},"13":{"q":"Tình huống: Multi-Agent Research — Trong production, bạn quan sát thấy các truy vấn kiểm tra sự kiện đơn giản (fact-checking query) (ví dụ: \"Hiệp định Paris về khí hậu được ký năm nào?\") đi qua cả bốn subagent một cách tuần tự, tiêu tốn hơn 40 giây và một lượng token đáng kể cho mỗi truy vấn. Các nghiên cứu so sánh phức tạp thì được hưởng lợi từ toàn bộ pipeline. Phân phối truy vấn (query distribution) của bạn đa dạng và đang thay đổi khi người dùng khám phá ra các ứng dụng mới. Cách tiếp cận hiệu quả nhất để tối ưu hóa cho độ phức tạp truy vấn khác nhau là gì?","e":"Hướng dẫn nghiên cứu multi-agent của Anthropic khuyến nghị để agent lead/orchestrator điều chỉnh mức độ nỗ lực (effort) theo độ phức tạp của truy vấn, quyết định một cách linh động (dynamically) số lượng và loại subagent nào cần gọi cho mỗi truy vấn. Các đường tắt tĩnh (static fast-path) (A), routing theo pattern lập trình cứng (hand-coded) (B), và một classifier đã huấn luyện (trained classifier) cần dữ liệu gán nhãn (labeled data) và việc huấn luyện lại (retraining) (C) đều sẽ thất bại khi phân phối truy vấn đa dạng và đang thay đổi, trong khi phán đoán dựa trên LLM (LLM-based judgment) của coordinator thích ứng một cách tự nhiên mà không cần bảo trì.","o":{"A":"Tạo một đường đi nhanh (fast-path) cho các câu hỏi mang tính sự kiện (factual question) bỏ qua hoàn toàn subagent, định tuyến tất cả các truy vấn khác qua toàn bộ pipeline để đảm bảo tính thấu đáo của nghiên cứu.","B":"Triển khai routing dựa trên mẫu (pattern-based routing) phân loại truy vấn theo cấu trúc (một sự kiện đơn lẻ so với so sánh so với phân tích) và ánh xạ mỗi loại đến một tổ hợp subagent định trước.","C":"Huấn luyện một bộ phân loại độ phức tạp truy vấn (query complexity classifier) trên dữ liệu lịch sử đã gán nhãn để dự đoán tổ hợp subagent tối ưu, huấn luyện lại định kỳ khi các mẫu truy vấn thay đổi.","D":"Để coordinator phân tích mỗi truy vấn và quyết định một cách động (dynamically) nên gọi subagent nào dựa trên đánh giá của nó về yêu cầu của truy vấn."}},"14":{"q":"Coordinator cung cấp các chỉ dẫn chi tiết từng bước (step-by-step) cho subagent web search, quy định chính xác các câu truy vấn tìm kiếm (search query), thứ tự ưu tiên nguồn (source priority), và bộ lọc ngày tháng (date filter). Giám sát production cho thấy ba vấn đề: (1) subagent báo cáo \"kết quả không đủ\" (insufficient results) thay vì thử các cách tiếp cận khác khi các tìm kiếm được chỉ định trước thất bại, (2) chất lượng nghiên cứu giảm đối với các chủ đề mới nổi (emerging topic) không khớp với các pattern kỳ vọng, và (3) subagent hiếm khi phát hiện ra các nguồn liên quan gián tiếp (tangential source) có giá trị. Cách hiệu quả nhất để cải thiện khả năng thích ứng (adaptability) của subagent là gì?","e":"Hướng dẫn về agent và nghiên cứu multi-agent của Anthropic khuyến nghị delegate (ủy quyền) với các mục tiêu rõ ràng và tiêu chí thành công/chất lượng (success/quality criteria) thay vì các kịch bản quy trình mang tính áp đặt (prescriptive procedural script), để cho subagent có năng lực tự điều chỉnh chiến lược tìm kiếm của riêng nó — điều này khắc phục trực tiếp cả ba lỗi được quan sát thấy. Phương án B loại bỏ hoàn toàn hướng dẫn cần thiết (delegation thiếu chỉ định — under-specified delegation — là một failure mode đã biết), C chỉ vá lỗi (1), còn D thêm sự phức tạp cho coordinator trong khi vẫn giữ cách tiếp cận kịch bản cứng nhắc (brittle scripted approach).","o":{"A":"Chỉ định các mục tiêu nghiên cứu và tiêu chí chất lượng (độ bao phủ, sự đa dạng nguồn, tính mới) thay vì các bước quy trình, để subagent tự xác định chiến lược tìm kiếm của nó.","B":"Loại bỏ hoàn toàn các chi tiết quy trình, ủy quyền bằng các mục tiêu đơn giản như \"nghiên cứu X một cách kỹ lưỡng\" và dựa vào năng lực chung của subagent.","C":"Thêm các chỉ dẫn dự phòng (fallback directive) rõ ràng vào các instructions chi tiết: \"Nếu các tìm kiếm được chỉ định cho ra ít hơn N kết quả, hãy thử các cách diễn đạt query thay thế trước khi báo cáo thất bại.\"","D":"Triển khai một bước phân loại chủ đề, trong đó coordinator phân loại các yêu cầu là \"được xác định rõ\" (well-defined) hoặc \"mang tính khám phá\" (exploratory) và dùng phong cách instruction khác nhau cho mỗi loại."}},"15":{"q":"Agent document analysis có một tool analyze_document duy nhất nhận vào một document và một tham số instruction dạng văn bản tự do (free-text). Trong quá trình đánh giá (evaluation), các yêu cầu như \"trích xuất các chỉ số tài chính chính\" thường trả về các bản tóm tắt tường thuật (narrative summary), trong khi \"tóm tắt phương pháp luận\" đôi khi lại trả về các bảng dữ liệu thô (raw data table). Agent synthesis báo cáo rằng 35% kết quả phân tích cần phải yêu cầu lại (re-request) với các instruction được làm rõ. Cách hiệu quả nhất để cải thiện độ tin cậy (reliability) là gì?","e":"Hướng dẫn thiết kế tool (tool-design) cho agent của Anthropic khuyến nghị các tool có phạm vi hẹp (narrowly-scoped), chuyên biệt theo mục đích (purpose-specific) với các hợp đồng input/output (input/output contract) rõ ràng thay vì một tool văn bản tự do chung chung (generic). Các lỗi ở đây là sự mơ hồ về định dạng output (output-format ambiguity) giữa các loại tác vụ khác nhau (extraction so với summarization so với verification), và việc tách thành các tool chuyên dụng (dedicated tool) với các contract được định nghĩa rõ sẽ khắc phục vấn đề này một cách có cấu trúc (structurally); một enum (C) hay các mô tả (description) tốt hơn (D) vẫn để lại một contract output được đặc tả lỏng lẻo (loosely-specified) duy nhất, và việc phân loại trước (pre-classification) (B) không thay đổi giao diện tool (tool interface) không đáng tin cậy.","o":{"A":"Tách tool chung chung thành các tool chuyên dụng theo mục đích (purpose-specific tool) — extract_data_points, summarize_content, verify_claim_against_source — mỗi tool có hợp đồng input/output được định nghĩa rõ ràng.","B":"Để coordinator phân loại trước mỗi yêu cầu phân tích trước khi truyền instructions cho agent phân tích tài liệu.","C":"Giữ nguyên một tool duy nhất nhưng thêm một tham số enum analysis_type yêu cầu lựa chọn rõ ràng giữa các chế độ extraction, summarization, và verification.","D":"Bổ sung mô tả tool với các ví dụ chi tiết cho thấy các cách diễn đạt instruction khác nhau nên được ánh xạ đến các định dạng output khác nhau như thế nào."}},"16":{"q":"Sau khi agent web search và agent document analysis hoàn thành tác vụ của chúng, coordinator gọi agent synthesis. Tuy nhiên, agent synthesis phản hồi rằng nó không thể hoàn thành tác vụ vì không có phát hiện nghiên cứu (research finding) nào được cung cấp. Nguyên nhân khả dĩ nhất của vấn đề này là gì?","e":"Trong pattern multi-agent coordinator/orchestrator, mỗi lệnh gọi subagent là một lệnh gọi API không trạng thái (stateless invocation) với context bị cô lập (isolated) riêng của nó — không có việc chia sẻ context tự động giữa các agent. Coordinator phải chủ động chèn (inject) output của các agent trước đó vào prompt của agent synthesis; nếu không làm vậy sẽ tạo ra chính xác phản hồi \"không có research finding nào được cung cấp\" này. Các phương án A–C đều sai: tràn context window (context-window overflow) sẽ gây ra một lỗi khác, và cũng không có tool lấy lịch sử liên-agent (cross-agent history-fetching tool) hay một kết nối API dùng chung (shared API connection) nào là cách context được truyền giữa các agent.","o":{"A":"Context window của synthesis agent không đủ lớn để chứa các output kết hợp từ cả hai agent trước đó.","B":"Synthesis agent cần các tool có thể lấy kết quả trực tiếp từ lịch sử hội thoại (conversation history) của các agent khác.","C":"Các subagent cần chia sẻ một kết nối API duy nhất để cho phép chia sẻ context tự động giữa các lần gọi.","D":"Coordinator đã không đưa các output từ các agent trước đó vào prompt của synthesis agent."}},"17":{"q":"Tình huống: Multi-Agent Research System. Giám sát production cho thấy các truy vấn tiếp nối (follow-up query) như \"tóm tắt những gì chúng ta đã tìm hiểu được về xu hướng thị trường\" liên tục mất hơn 40 giây. Điều tra cho thấy coordinator spawn subagent synthesis cho mỗi yêu cầu tóm tắt, truyền vào hơn 80K token các phát hiện đã tích lũy (accumulated findings). Coordinator đã có sẵn các phát hiện này trong context của nó từ việc điều phối (orchestrate) nghiên cứu. Cách hiệu quả nhất để cải thiện thời gian phản hồi cho các bản tóm tắt tiếp nối này là gì?","e":"Coordinator đã có sẵn toàn bộ findings trong context của nó, vì vậy việc spawn một subagent và truyền lại hơn 80K token cho mỗi bản tóm tắt hoàn toàn chỉ là chi phí phụ trội (overhead) về latency. Best practice về multi-agent của Anthropic là chỉ delegate cho subagent khi các context window riêng biệt hoặc tính song song (parallelism) mang lại giá trị; việc tóm tắt đơn giản nên được chính orchestrator xử lý trực tiếp, loại bỏ cả chi phí spawn lẫn việc truyền token.","o":{"A":"Tạo trước và cache các bản tóm tắt ở nhiều mức độ chi tiết (granularity) khác nhau mỗi khi có phát hiện mới được tích lũy.","B":"Bật prompt caching trên synthesis subagent để giảm chi phí phát sinh (overhead) do phải truyền lặp lại cùng một kết quả nghiên cứu.","C":"Để coordinator tự xử lý trực tiếp các yêu cầu tóm tắt đơn giản bằng context hiện có của nó, chỉ dành việc sinh subagent cho các task phân tích phức tạp.","D":"Sinh ra synthesis subagent với context bị rút gọn và để nó yêu cầu các phát hiện cụ thể từ coordinator theo yêu cầu (on-demand)."}},"18":{"q":"Agent synthesis nhận các phát hiện đã được tóm tắt từ các agent web search và document analysis, sau đó truyền một bản tóm tắt hợp nhất (consolidated summary) cho report generator. Trong quá trình testing, bạn phát hiện ra rằng các báo cáo được tạo ra đưa ra các luận điểm thực tế (factual claim) mà không có trích dẫn phù hợp — report generator không thể quy chiếu (attribute) các phát biểu về nguồn gốc ban đầu của chúng vì metadata đó đã bị mất trong các bước tóm tắt. Cách tiếp cận hiệu quả nhất để đảm bảo việc quy chiếu nguồn (source attribution) đúng trong các báo cáo cuối cùng là gì?","e":"Structured output tách biệt rõ ràng nội dung tóm tắt khỏi metadata nguồn (URL, tên tài liệu, số trang) đảm bảo nguồn gốc (provenance) được giữ nguyên qua mọi lần bàn giao (handoff) trong pipeline, đây là pattern được Anthropic khuyến nghị cho luồng dữ liệu (data flow) multi-agent. Trích dẫn nội tuyến (inline citation) trong văn bản tự do (A) dễ bị mất hoặc làm sai lệch trong quá trình tóm tắt ở các bước sau, việc xác định lại vị trí nguồn sau khi sự việc đã xảy ra (re-locating sources after the fact) (B) không đáng tin cậy và có thể quy chiếu sai luận điểm, còn việc truyền các output thô (C) làm mất đi mục đích của việc tóm tắt và làm phình to context của report generator.","o":{"A":"Yêu cầu synthesis agent nhúng các tham chiếu nguồn (source reference) inline trong văn bản tóm tắt của nó, dùng một định dạng citation nhất quán.","B":"Để report generator truy vấn web search agent để định vị lại các nguồn cho các claim trong báo cáo cuối cùng.","C":"Bỏ qua bước summarization và truyền toàn bộ output thô (raw output) từ web search và document analysis trực tiếp cho report generator.","D":"Để mỗi agent xuất ra dữ liệu có cấu trúc, tách riêng phần tóm tắt nội dung khỏi metadata nguồn (URL, tên tài liệu, số trang)."}},"19":{"q":"Sau khi agent web search tìm được 25 nguồn (120K token nội dung thô), agent document analysis trích xuất các insight chính (15K token), và agent synthesis tạo ra một bản nháp tường thuật mạch lạc (coherent narrative draft) (3K token), coordinator phải truyền context cho agent report generation để tạo ra output cuối cùng với các trích dẫn nguồn phù hợp. Chiến lược truyền context (context-passing strategy) nào mang lại sự cân bằng tốt nhất giữa tính đầy đủ (completeness) và hiệu quả (efficiency)?","e":"Bản synthesis cung cấp phần tường thuật; chỉ mục nguồn (source index) cung cấp cho report generator chính xác sự ràng buộc (binding) nó cần để trích dẫn mà không phải đọc lại 120K token nội dung thô. Việc khớp nối sau sự việc (post-hoc matching) (A) mong manh và dễ quy chiếu sai, việc quy chiếu chỉ bằng tên (name-only attribution) (C) làm mất URL và các đoạn trích (excerpt) cần thiết để trích dẫn hoặc xác minh, và việc truyền toàn bộ context đã tích lũy (D) là lãng phí vì hầu hết hơn 120K token thô chỉ là nhiễu (noise) không liên quan ở giai đoạn này.","o":{"A":"Chỉ truyền bản nháp synthesis (synthesis draft) và dùng một pipeline hậu xử lý (post-processing) riêng biệt để khớp các claim với nguồn và chèn citation sau khi báo cáo đã được tạo ra.","B":"Truyền bản nháp synthesis kèm theo một chỉ mục nguồn có cấu trúc (structured source index) ánh xạ các claim chính đến URL nguồn và các đoạn trích liên quan.","C":"Truyền một bản tóm tắt cô đọng (condensed summary) của tất cả các giai đoạn trước, giữ lại các phát hiện chính và gán chúng cho nguồn chỉ bằng tên.","D":"Truyền toàn bộ context tích lũy từ tất cả các agent trước đó."}},"20":{"q":"Agent web search đã thu thập được một số nguồn liên quan cho một chủ đề nghiên cứu. Agent document analysis giờ cần xem xét các nguồn này. Thông tin thường chảy (flow) giữa hai subagent chuyên biệt này như thế nào?","e":"Trong pattern orchestrator-worker, coordinator là trung tâm (hub): nó thu thập output của mỗi subagent và chủ động chuyển tiếp (forward) các phần liên quan vào prompt của subagent tiếp theo. Event bus (A) không phải là một phần của mô hình subagent của Claude, các subagent không thể trực tiếp gọi các subagent anh em (sibling subagent) (B) vì điều đó sẽ ràng buộc chúng quá chặt (tightly couple) và phá vỡ pattern orchestrator, còn một kho lưu trữ dùng chung (shared store) (D) có thể được thêm vào như một tối ưu hóa nhưng không phải cách các subagent thường giao tiếp và gây ra vấn đề đọc dữ liệu cũ (stale-read).","o":{"A":"Các agent giao tiếp thông qua một message queue theo hướng sự kiện (event-driven), với document analysis agent đăng ký (subscribing) nhận các sự kiện hoàn tất của web search.","B":"Web search agent gọi trực tiếp document analysis agent, truyền các nguồn đã phát hiện được như các tham số.","C":"Coordinator agent nhận output của web search agent và đưa các phát hiện liên quan vào prompt khi gọi document analysis agent.","D":"Cả hai agent cùng truy cập một shared memory store, trong đó web search agent ghi các phát hiện và document analysis agent đọc chúng."}},"21":{"q":"Khi nghiên cứu về \"sự chấp nhận năng lượng tái tạo\" (renewable energy adoption), web search agent trả về các số liệu thống kê gần đây (năm 2024: tỷ lệ chấp nhận 35%), trong khi document analysis agent trích xuất dữ liệu từ các báo cáo nội bộ (năm 2022: tỷ lệ chấp nhận 18%). Synthesis agent lại đánh dấu nhầm đây là các nguồn mâu thuẫn nhau thay vì nhận ra rằng dữ liệu cho thấy sự tăng trưởng theo thời gian. Thay đổi nào sẽ giúp synthesis agent diễn giải đúng các khác biệt về mặt thời gian (temporal differences) như vậy?","e":"Synthesis agent hiểu sai dữ liệu vì nó không bao giờ thấy được các mốc thời gian (dates). Việc để mỗi điểm dữ liệu mang theo dấu thời gian (timestamp) riêng trong structured output cho phép synthesis agent suy luận về xu hướng (trends) thay vì mâu thuẫn. Việc âm thầm loại bỏ dữ liệu cũ hơn (B) sẽ phá hủy thông tin về xu hướng, việc thu hẹp khung thời gian (C) vứt bỏ bối cảnh lịch sử mà không khắc phục được lỗ hổng kiến trúc, và chỉ dùng hướng dẫn trong prompt (D) là không đáng tin cậy và vẫn che giấu việc suy luận theo thời gian đằng sau một quy tắc cứng nhắc.","o":{"A":"Yêu cầu các subagent đưa vào ngày xuất bản hoặc ngày thu thập dữ liệu trong structured output của chúng.","B":"Thêm một agent giải quyết xung đột (conflict resolution agent) để tự động loại bỏ dữ liệu cũ hơn khi có dữ liệu mới hơn cho cùng một chỉ số (metric).","C":"Cấu hình web search agent chỉ trả về kết quả trong 6 tháng gần nhất.","D":"Yêu cầu synthesis agent luôn coi dữ liệu gần đây nhất là có thẩm quyền (authoritative) và đặt các phát hiện cũ hơn vào một phụ lục lịch sử riêng."}},"22":{"q":"Các đánh giá production cho thấy việc xử lý sự không chắc chắn (uncertainty) trong các báo cáo cuối cùng không nhất quán. Đôi khi các phát hiện mâu thuẫn nhau từ các subagent được tổng hợp thành một phát biểu chắc chắn duy nhất (làm mất đi sắc thái - nuance), trong khi những lúc khác báo cáo lại rào đón (hedge) quá mức với quá nhiều điều kiện (trở nên vô ích). Khi web search agent trả về \"các nhà phân tích ngành ước tính quy mô thị trường $50B (phương pháp luận khác nhau)\" và document analysis agent trả về \"nghiên cứu bình duyệt (peer-reviewed) ước tính $35B (±$7B, khoảng tin cậy 95%)\", coordinator hoặc chọn một cách tùy tiện hoặc đưa ra các phát biểu mơ hồ như \"thị trường có thể là $35B−$50B tùy thuộc vào các yếu tố.\" Cách tiếp cận có hệ thống nào giải quyết tốt nhất vấn đề này?","e":"Cấu trúc báo cáo giữ lại bối cảnh phương pháp luận (methodological context) và tách biệt các nhận định đã được xác lập với các nhận định còn tranh cãi là cách để đạt được sắc thái (nuance) mà không rào đón quá mức. Việc lọc bỏ (A) vứt đi các bằng chứng hữu ích nhưng không chắc chắn, việc gộp các phương pháp luận khác nhau thành một con số trung bình (B) phá hủy chính sự khác biệt về phương pháp luận vốn là trọng tâm của vấn đề, và yêu cầu tối thiểu hai nguồn (D) loại bỏ các phát hiện hợp lệ chỉ có một nguồn và không giải quyết được các ước tính thực sự mâu thuẫn nhau.","o":{"A":"Cấu hình các subagent chỉ báo cáo những phát hiện đạt ngưỡng độ tin cậy cao (high-confidence threshold), lọc bỏ thông tin không chắc chắn trước khi nó đến được coordinator.","B":"Triển khai một lớp hiệu chỉnh độ tin cậy (confidence calibration layer) để chuẩn hóa các biểu đạt không chắc chắn của subagent thành điểm xác suất chuẩn hóa (0.0-1.0), sau đó tính trung bình có trọng số (weight-average) các phát hiện theo độ tin cậy đã hiệu chỉnh.","C":"Yêu cầu synthesis agent cấu trúc báo cáo với các phần rõ ràng phân biệt những phát hiện đã được xác lập vững chắc với những phát hiện còn gây tranh cãi, đồng thời giữ nguyên cách mô tả nguồn gốc ban đầu và bối cảnh phương pháp luận.","D":"Thêm một verification subagent để đối chiếu chéo các phát hiện giữa các nguồn, chỉ chuyển sang synthesis những nhận định (claims) được xác nhận bởi ít nhất hai nguồn độc lập."}},"23":{"q":"Bạn đang xây dựng một quy trình quét bảo mật (security scanning workflow). Khi các kỹ sư cần định vị tất cả các lần xuất hiện của một hàm nguy hiểm như eval() trong một codebase lớn, agent của bạn nên dùng công cụ nào để tìm kiếm nội dung (content search)?","e":"Grep là công cụ tìm kiếm nội dung (content-search) chuyên dụng (dựa trên ripgrep) để tìm các pattern bên trong nội dung file trên một codebase lớn, đây chính xác là điều cần thiết để định vị tất cả các vị trí gọi eval(. Glob chỉ khớp tên file, việc đọc các file entry và truy vết các import không có khả năng mở rộng (scale) hoặc đảm bảo độ bao phủ, và ls -R | grep cũng chỉ khớp tên file chứ không khớp nội dung file.","o":{"A":"Dùng Glob với pattern như /*eval* để tìm file, sau đó Read từng file khớp.","B":"Dùng Grep để tìm kiếm pattern \"eval(\" trên toàn bộ file trong codebase.","C":"Read file entry chính của dự án và lần theo các import statement để truy vết nơi eval có thể được sử dụng.","D":"Dùng Bash để chạy ls -R | grep eval nhằm liệt kê đệ quy các file chứa eval."}},"24":{"q":"Kịch bản: Năng suất của nhà phát triển (Developer Productivity) — Các kỹ sư thường xuyên yêu cầu agent đối chiếu các thay đổi mã nguồn (code changes) với các ticket Jira trong quá trình review — kiểm tra mô tả ticket, tiêu chí chấp nhận (acceptance criteria), và các bình luận gần đây. Hiện tại việc này đòi hỏi phải copy-paste nội dung thủ công vào các cuộc hội thoại. Nhóm muốn agent truy cập trực tiếp vào dữ liệu ticket Jira tiêu chuẩn này. Đâu là cách tiếp cận hiệu quả nhất?","e":"Đối với dữ liệu dịch vụ bên thứ ba tiêu chuẩn như ticket Jira, khuyến nghị của Anthropic là tích hợp một MCP server đã có sẵn, vì nó cung cấp các giao diện tool có thể khám phá được (discoverable), có kiểu (typed) với xác thực (authentication) được quản lý. Việc xây dựng một MCP server tùy chỉnh (B) là nỗ lực không cần thiết cho dữ liệu ticket tiêu chuẩn, việc export ra markdown (A) sẽ nhanh chóng lỗi thời và đòi hỏi đồng bộ thủ công, và các lệnh gọi curl tùy biến (ad-hoc) (D) dễ hỏng (brittle) và để lộ thông tin xác thực (credentials) ngay trong mã.","o":{"A":"Xuất (export) các ticket Jira thành file markdown trong repository để agent truy cập bằng tool Read.","B":"Xây dựng một MCP server tùy chỉnh (custom) bọc quanh API của Jira với các tool được thiết kế riêng cho quy trình code review của nhóm này.","C":"Tích hợp một Jira MCP server có sẵn, cung cấp ticket, comment và metadata thông qua các tool interface có thể discover được.","D":"Dùng tool Bash với curl để gọi REST API của Jira, bao gồm cả authentication header và parse JSON response trực tiếp trong luồng xử lý."}},"25":{"q":"Kịch bản: Năng suất của nhà phát triển (Developer Productivity) — Một kỹ sư yêu cầu agent tìm tất cả các file trong monorepo có import package @company/auth để hiểu cách xác thực (authentication) được sử dụng trên các service. Công cụ built-in nào phù hợp nhất cho tác vụ này?","e":"Nhiệm vụ là tìm mọi file có nội dung chứa import @company/auth, đây là một bài toán tìm kiếm nội dung (content-search) — chính xác là điều mà công cụ built-in Grep (dựa trên ripgrep) được thiết kế để làm. Glob và find/Bash chỉ khớp tên file hoặc tên thư mục, điều này sẽ bỏ sót nhiều file có import nhưng không có \"auth\" trong đường dẫn, và việc đọc các file package.json chỉ cho thấy các dependency được khai báo, không phải các vị trí sử dụng thực tế.","o":{"A":"Bash, để chạy find . -type d -name \"*auth*\" và khám phá các thư mục khớp","B":"Read, bắt đầu từ các file package.json để lần theo khai báo dependency","C":"Grep, để tìm kiếm pattern của import statement trong nội dung file","D":"Glob, để tìm các file có \"auth\" trong tên file hoặc đường dẫn"}},"26":{"q":"Agent năng suất của bạn kết nối với ba MCP server: một issue tracker (search_issues, get_issue, create_comment), một wiki tài liệu (search_docs, get_page, list_spaces), và một database explorer (run_query, get_schema, list_databases). Khi các kỹ sư đặt các câu hỏi liên hệ thống (cross-system) như \"Những bảng cơ sở dữ liệu nào bị ảnh hưởng bởi việc tái cấu trúc (refactor) xác thực trong PROJ-1234?\", giám sát cho thấy agent thực hiện 8-10 lệnh gọi tool tuần tự, thường xuyên đưa ra các lệnh gọi thăm dò (exploratory) vì nó thiếu khả năng nhìn thấy nội dung mà mỗi server chứa, và cạn kiệt không gian context trước khi hoàn thành các cuộc điều tra phức tạp. Thay đổi kiến trúc nào tận dụng tốt nhất các khả năng của MCP để giải quyết những vấn đề này?","e":"MCP resources là nguyên hàm (primitive) của giao thức được thiết kế chính xác cho vấn đề này: các server expose context có thể duyệt được (browsable), do ứng dụng kiểm soát (application-controlled) (tóm tắt issue, cấu trúc phân cấp tài liệu, schema cơ sở dữ liệu) mà agent có thể khám phá và đọc mà không cần các vòng lặp gọi tool thăm dò, khắc phục trực tiếp lỗ hổng về khả năng nhìn thấy và tình trạng cạn kiệt context. Phương án A xây dựng lại một khối nguyên (monolith) đi ngược với thiết kế mô-đun hóa (composable) của MCP, C chỉ thêm nhiều tool hơn mà không tận dụng các khả năng của MCP, và việc định tuyến theo từ khóa (keyword routing) đơn server của D vốn dĩ không xử lý được các câu hỏi liên hệ thống.","o":{"A":"Hợp nhất cả ba server thành một MCP server thống nhất có khả năng đối chiếu chéo (cross-referencing)","B":"Expose danh mục nội dung của mỗi server dưới dạng MCP resources—tóm tắt issue, cấu trúc phân cấp tài liệu, database schema","C":"Thêm một tool prepare_investigation cho mỗi server, nhận vào một câu hỏi bằng ngôn ngữ tự nhiên và trả về các tóm tắt nội dung liên quan","D":"Thêm một orchestrator định tuyến câu hỏi đến một server duy nhất dựa trên từ khóa"}},"27":{"q":"Kịch bản: Multi-Agent Research — Bạn đã cấu hình hệ thống sao cho cả bốn subagent đều có quyền truy cập vào toàn bộ 18 tool. Trong quá trình kiểm thử, các agent thường xuyên gọi các tool nằm ngoài chuyên môn của chúng — synthesis agent thử thực hiện tìm kiếm web, và report generator thử phân tích tài liệu. Đâu là nguyên nhân chính của hành vi lựa chọn tool kém này?","e":"Các thực hành tốt nhất (best practices) của Anthropic về agent khuyến nghị chỉ cung cấp cho mỗi subagent một tập tool nhỏ, liên quan đến vai trò của nó, vì độ chính xác trong việc lựa chọn tool suy giảm khi số lượng tool khả dụng (đặc biệt là các tool không liên quan) tăng lên. Khi cả 18 tool đều được expose cho mọi agent, mô hình phải đối mặt với một không gian quyết định lớn hơn và có thể đoán trước là sẽ chọn các tool nằm ngoài chuyên môn của nó — nguyên nhân gốc rễ là độ phức tạp trong lựa chọn, chứ không phải việc theo dõi của coordinator, xung đột prompt, hay cạn kiệt context window.","o":{"A":"Việc phải chọn từ 18 tool thay vì 4-5 tool liên quan làm tăng độ phức tạp của quyết định vượt quá ngưỡng lựa chọn đáng tin cậy.","B":"Coordinator không thể theo dõi được subagent nào có capability nào, dẫn đến việc định tuyến task sai.","C":"Mô tả vai trò (role) của các agent trong system prompt của chúng mâu thuẫn với việc có quyền truy cập các tool nằm ngoài vai trò đó.","D":"Các tool definition chiếm quá nhiều không gian trong context window, không còn đủ chỗ cho nội dung task."}},"28":{"q":"Một khách hàng quay lại 4 giờ sau phiên làm việc (session) ban đầu của họ về cùng một tranh chấp hóa đơn (billing dispute). Phiên trước gồm 32 lượt (turn) chứa kết quả lookup_order cho thấy \"Status: PENDING, Expected resolution: 24-48 hours.\" Trong quá trình kiểm thử, bạn quan sát thấy rằng khi tiếp tục các phiên có kết quả tool đã cũ (stale tool results), agent thường tham chiếu đến dữ liệu lỗi thời trong các phản hồi (ví dụ: \"Tôi thấy khoản hoàn tiền của bạn vẫn đang được xử lý\") ngay cả sau khi các lệnh gọi tool mới hơn trả về thông tin khác. Cách tiếp cận nào xử lý khách hàng quay lại một cách đáng tin cậy nhất?","e":"Một session sạch với một bản tóm tắt có cấu trúc (structured summary) giữ được tính liên tục của mạch chuyện trong khi vẫn đảm bảo agent không suy luận dựa trên các kết quả tool đã cũ. Việc loại bỏ tool_results ở giữa cuộc hội thoại (A) có thể để lại các tin nhắn của assistant tham chiếu đến các kết quả không còn tồn tại, hướng dẫn trong prompt (C) chỉ là gợi ý mà việc kiểm thử đã cho thấy là thất bại, và việc gọi lại toàn bộ mọi thứ (D) là lãng phí và vẫn để các kết quả cũ nằm trong context gây nhầm lẫn cho mô hình.","o":{"A":"Resume với toàn bộ lịch sử nhưng lọc bỏ các message tool_result trước đó trước khi resume, chỉ giữ lại các lượt human/assistant để agent phải fetch lại dữ liệu cần thiết.","B":"Bắt đầu một session mới, chèn vào một bản tóm tắt có cấu trúc (structured summary) của tương tác trước đó (loại vấn đề, các hành động đã thực hiện, tình trạng giải quyết), sau đó thực hiện các tool call mới trước khi tiếp tục xử lý.","C":"Resume với toàn bộ lịch sử và thêm một chỉ dẫn trong system prompt yêu cầu agent luôn ưu tiên tool result gần nhất khi có nhiều lần gọi cùng một tool trong context.","D":"Resume với toàn bộ lịch sử và cấu hình agent tự động gọi lại tất cả các tool đã dùng trước đó ngay khi bắt đầu session để đảm bảo dữ liệu mới nhất."}},"29":{"q":"Bạn đang triển khai logic chuyển tiếp (escalation logic) cho việc khi nào agent nên gọi escalate_to_human. Nhóm của bạn đề xuất bốn cách tiếp cận khác nhau để kích hoạt việc chuyển tiếp (escalation). Cách tiếp cận nào sẽ nhận diện đáng tin cậy nhất các trường hợp thực sự cần có sự can thiệp của con người?","e":"Các quyết định chuyển tiếp (escalation) là các đánh giá chủ quan (judgment call) về ý định và tiến trình — đây chính xác là điều mà LLM làm tốt. Các tiêu chí rõ ràng bằng ngôn ngữ tự nhiên vượt trội hơn các quy tắc cứng nhắc đối với các trường hợp hiếm gặp (long tail). Một số lần thử lại cố định (hard retry count) (B) kích hoạt vừa quá sớm vừa quá muộn, phân tích cảm xúc (sentiment analysis) (C) bỏ sót những khách hàng bình tĩnh chỉ đơn giản cần một ngoại lệ về chính sách và chuyển tiếp quá mức đối với ngôn ngữ mang tính phong cách, và các hệ thống quy tắc (rules engines) (D) thất bại trên chính những trường hợp mà chúng không được thiết kế để xử lý, và bộ phận hỗ trợ (support) đầy rẫy những trường hợp như vậy.","o":{"A":"Yêu cầu agent escalate khi khách hàng yêu cầu gặp người thật, khi vấn đề cần ngoại lệ về chính sách (policy exception), hoặc khi agent không thể đạt được tiến triển đáng kể.","B":"Cấu hình agent escalate sau ba lần gọi tool liên tiếp không giải quyết được vấn đề khách hàng nêu ra, đảm bảo đã có một nỗ lực hợp lý trước khi chuyển cho người thật.","C":"Triển khai phân tích cảm xúc (sentiment analysis) theo dõi các dấu hiệu bực bội (ngôn ngữ tiêu cực, câu hỏi lặp lại, dấu chấm than) và kích hoạt escalation khi điểm bực bội (frustration score) vượt quá ngưỡng đã cấu hình.","D":"Xây dựng một rules engine ánh xạ các loại vấn đề cụ thể, phân khúc khách hàng và danh mục sản phẩm đến các quyết định escalation, loại bỏ nhu cầu phán đoán (judgment call) của model."}},"30":{"q":"Sau khi điều tra một tranh chấp hóa đơn (billing dispute) qua hơn 25 lượt (turn), bạn đã xác định rằng các khoản tính phí trùng lặp (duplicate charges) xảy ra do một timeout của cổng thanh toán (payment gateway) kích hoạt logic thử lại (retry logic). Khoản hoàn tiền cần thiết ($847) vượt quá giới hạn ủy quyền (authorization limit) $500 của bạn. Bạn cần gọi escalate_to_human, và nhân viên con người sẽ không có quyền truy cập vào transcript cuộc hội thoại của bạn. Bạn nên truyền context nào để việc giải quyết được hiệu quả?","e":"Một bàn giao (handoff) có cấu trúc với các định danh (identifiers), nguyên nhân, số tiền, và hành động được đề xuất là những gì một nhân viên con người cần để tiếp nhận vụ việc ngay lập tức mà không cần điều tra lại. Các dữ liệu thô (raw artifacts) không qua tổng hợp (synthesis) (A) buộc nhân viên con người phải làm lại 25 lượt điều tra, việc đổ toàn bộ transcript (C) buộc nhân viên con người phải lội qua nó thay vì đọc một bản tóm tắt gọn trong một màn hình, và phương án D thiếu các định danh khách hàng và một hành động được đề xuất mà nhân viên con người không thể hành động nếu thiếu.","o":{"A":"Nguyên văn khiếu nại ban đầu của khách hàng cộng với các đoạn trích tool result cho thấy các giao dịch trùng lặp (duplicate transactions).","B":"Một bản tóm tắt có cấu trúc: customer ID, nguyên nhân gốc rễ (root cause), số tiền hoàn trả (refund amount), và hành động được đề xuất.","C":"Toàn bộ transcript của cuộc hội thoại cùng với tất cả tool result.","D":"Chỉ chẩn đoán của bạn và số tiền hoàn trả."}},"31":{"q":"Tuân thủ (compliance) yêu cầu rằng các khoản hoàn tiền vượt quá $500 phải tự động chuyển tiếp (escalate) đến nhân viên con người — quy tắc này không được để cho mô hình tùy ý quyết định. Mặc dù có hướng dẫn rõ ràng trong system prompt, log production cho thấy agent đôi khi xử lý trực tiếp các khoản hoàn tiền giá trị cao (tỷ lệ thất bại 3%). Bạn nên làm gì để đạt được sự tuân thủ (compliance) được đảm bảo?","e":"Các quy tắc ở cấp độ tuân thủ (compliance-grade) thuộc về bên ngoài mô hình — một hook tất định (deterministic) trên lệnh gọi tool đảm bảo sẽ luôn kích hoạt mỗi lần, độc lập với hành vi của mô hình. Việc trả về một thông báo lỗi (A) vẫn phụ thuộc vào việc agent diễn giải đúng nó, các ví dụ few-shot (B) dịch chuyển phân phối (distribution) nhưng không loại bỏ tỷ lệ thất bại, và ngôn ngữ nhấn mạnh trong prompt (D) làm giảm nhưng không loại bỏ việc sử dụng sai — yêu cầu rằng điều này không được để cho mô hình tùy ý quyết định loại trừ mọi giải pháp chỉ dựa trên prompt.","o":{"A":"Sửa đổi refund tool để trả về lỗi với message \"Amount exceeds policy limit—please escalate\" khi vượt ngưỡng (threshold).","B":"Thêm few-shot example vào prompt minh họa hành vi escalation đúng ở các mức số tiền hoàn trả khác nhau ($400, $500, $600).","C":"Triển khai một hook để chặn (intercept) các tool call; khi số tiền của process_refund vượt quá $500, chặn nó lại và gọi human escalation.","D":"Tăng cường system prompt bằng ngôn ngữ nhấn mạnh: \"CRITICAL POLICY: Refunds over $500 MUST trigger human escalation. NEVER process these directly.\""}},"32":{"q":"Trong quá trình giải quyết một tranh chấp hóa đơn (billing dispute), agent của bạn lấy thành công thông tin khách hàng qua get_customer và chi tiết đơn hàng qua lookup_order, nhưng khi cố gắng gọi process_refund, tool trả về lỗi timeout. Agent có đủ thông tin để giải thích các khoản phí và xác minh tính đủ điều kiện hoàn tiền, nhưng không thể thực sự xử lý khoản hoàn tiền do lỗi ở backend. Cách tiếp cận nào cân bằng tốt nhất giữa việc giải quyết ngay từ lần liên hệ đầu tiên (first-contact resolution) và việc xử lý lỗi phù hợp?","e":"Cung cấp giá trị một phần mà bạn có thể (giải thích + tính đủ điều kiện), trung thực về sự cố, và để khách hàng lựa chọn giữa việc chuyển tiếp cho con người hoặc thử lại — đây là kiểu graceful degradation (suy giảm graceful) kinh điển. Việc chuyển tiếp ngay lập tức (A) đẩy một sự cố backend tạm thời đi trong khi agent vẫn có thể giải thích tình huống, việc thử lại vô thời hạn (B) là trải nghiệm người dùng (UX) kém và có thể không bao giờ thành công trong một đợt gián đoạn (outage) kéo dài, và việc xác nhận một kết quả chưa thực sự xảy ra (D) đánh lừa khách hàng, một thất bại còn lớn hơn cả chính lỗi timeout.","o":{"A":"Escalate ngay lập tức cho một human agent vì hành động hoàn tiền không thể hoàn tất","B":"Triển khai retry tự động với exponential backoff cho process_refund, giữ cuộc hội thoại mở cho đến khi khoản hoàn tiền được xử lý thành công","C":"Giải thích về khoản phí (billing), xác nhận khách hàng đủ điều kiện hoàn tiền (refund eligibility), thừa nhận sự cố hệ thống đang ngăn việc xử lý ngay lập tức, và đề nghị escalation hoặc thử lại sau","D":"Xác nhận khoản hoàn tiền sẽ được xử lý và đóng cuộc hội thoại, vì hệ thống đã có đủ thông tin cần thiết để tự động hoàn tất việc này"}},"33":{"q":"Một khách hàng viết: \"Tôi đã qua lại về việc trả hàng này mấy ngày rồi. Tôi chỉ muốn nói chuyện với ai đó có thể thực sự giúp tôi.\" Agent đã xác nhận qua lookup_order rằng việc trả hàng là đơn giản — nằm trong chính sách và đủ điều kiện để xử lý ngay lập tức. Agent nên làm gì?","e":"Tôn trọng cảm xúc của khách hàng, cung cấp cho họ con đường giải quyết nhanh bằng văn bản, và bảo toàn quyền lựa chọn của họ — đó là hành động tôn trọng khách hàng mà vẫn tận dụng được năng lực của agent. Việc chuyển tiếp ngay lập tức (B) là xếp hàng chờ không cần thiết khi vấn đề chỉ cách một lệnh gọi tool, việc xử lý đơn phương (C) ghi đè lên nguyện vọng đã nêu rõ ràng của khách hàng là muốn nói chuyện với ai đó, và việc thẩm vấn khách hàng về các thất bại trong quá khứ (D) hoàn toàn trái ngược với điều họ yêu cầu.","o":{"A":"Thừa nhận sự bực bội của khách hàng, cho họ biết vấn đề này có thể giải quyết được ngay bây giờ, và đề nghị hoàn tất hoặc escalate","B":"Gọi escalate_to_human ngay lập tức để tôn trọng yêu cầu của khách hàng","C":"Xử lý hoàn tiền qua process_refund để giải quyết vấn đề gốc rễ, sau đó thông báo cho khách hàng rằng đã hoàn tất","D":"Hỏi cụ thể điều gì đã không hiệu quả trong các lần thử trước đó trước khi quyết định escalate hay tự giải quyết"}},"34":{"q":"Agent xác minh danh tính khách hàng qua một quy trình nhiều bước trước khi đặt lại mật khẩu. Trong quá trình kiểm thử, bạn nhận thấy rằng sau khi khách hàng trả lời câu hỏi xác minh thứ ba, agent lại yêu cầu họ cung cấp tên một lần nữa, như thể trao đổi trước đó chưa từng xảy ra. Nguyên nhân nào có khả năng nhất gây ra hành vi này?","e":"API là không trạng thái (stateless) — mỗi request phải bao gồm toàn bộ mảng messages. Nếu bạn chỉ gửi lượt (turn) mới nhất, mô hình sẽ không có ký ức về các lượt trước đó, chính xác là triệu chứng \"hỏi lại tên\" này. Tool không xóa trạng thái của agent (A), việc ghi nhớ qua các lượt không đạt được bằng một hướng dẫn (instruction) (B) mà bằng cách truyền các lượt trước đó vào request tiếp theo, và không hề tồn tại giới hạn mặc định hai lượt như vậy (D) — context chỉ bị giới hạn bởi context window.","o":{"A":"Verification tool đang xóa internal state của agent sau mỗi bước validation thành công.","B":"Prompt thiếu chỉ dẫn yêu cầu Claude ghi nhớ thông tin qua nhiều lượt trao đổi.","C":"Conversation history không được truyền vào trong các API request tiếp theo.","D":"Khả năng ghi nhớ (memory retention) của Claude mặc định chỉ giới hạn ở hai lượt hội thoại, cần cấu hình rõ ràng để mở rộng."}},"35":{"q":"Log production cho thấy việc xử lý lỗi không nhất quán: khi lookup_order thất bại, agent đôi khi thử lại 5 lần trở lên (lãng phí khi order ID không tồn tại), đôi khi chuyển tiếp (escalate) ngay lập tức (quá sớm đối với các sự cố mạng tạm thời), và đôi khi hỏi người dùng để làm rõ (không phù hợp khi vấn đề là lỗi phân quyền backend). Điều tra cho thấy MCP tool của bạn trả về các phản hồi lỗi đồng nhất: {\"isError\": true, \"content\": [{\"type\": \"text\", \"text\": \"Operation failed\"}]}. Agent không thể phân biệt giữa các loại lỗi. Cải tiến nào hiệu quả nhất?","e":"Cung cấp cho agent thông tin nó cần để đưa ra quyết định đúng: loại lỗi (category), khả năng thử lại (retryability), và một nguyên nhân dễ đọc cho con người. Điều đó thay thế việc đoán mò bằng chính sách tất định (deterministic policy). Một tool analyze_error bổ sung (B) thêm một vòng gọi round-trip cho thông tin mà tool gốc đã biết sẵn, việc thử lại vô điều kiện (blanket retries) (C) gây hại trên các lỗi vĩnh viễn (permanent errors) và che giấu các phân biệt hữu ích, và các ví dụ few-shot (D) không thể trích xuất thông tin category không hề có mặt trong một chuỗi \"Operation failed\" đồng nhất.","o":{"A":"Cải thiện error response bằng structured metadata: bao gồm errorCategory (transient/validation/permission), boolean isRetryable, và mô tả nguyên nhân gây ra lỗi.","B":"Tạo một MCP tool tên analyze_error mà agent gọi sau mỗi lần thất bại để xác định loại lỗi (error category) và hành động được đề xuất.","C":"Triển khai retry logic với exponential backoff trong MCP server của bạn cho tất cả các lỗi, chỉ trả về cho agent sau khi retry đã hết lượt.","D":"Thêm few-shot example vào system prompt minh họa cách diễn giải các pattern trong error message và chọn phản hồi phù hợp cho từng loại."}},"36":{"q":"Khi agent gọi lookup_order và nhận được chi tiết đơn hàng cho thấy sản phẩm được mua cách đây 45 ngày, agentic loop xác định như thế nào việc gọi process_refund hay escalate_to_human tiếp theo?","e":"Agentic loop hoạt động bằng cách gắn thêm các tin nhắn tool_result vào cuộc hội thoại và để mô hình quyết định bước tiếp theo ở mỗi lượt (turn) — đó là cách quyết định hoàn tiền so với chuyển tiếp cho trường hợp 45 ngày được giải quyết. Không có một lớp điều phối (orchestration layer) ngầm nào chọn tool từ một trường (field) (A), agentic loop được điều khiển bởi mô hình (model-driven) chứ không phải bởi cây quyết định (decision-tree-driven) (B), và không có một kế hoạch cam kết trước (upfront committed plan) nào (D) vì agent chọn từng bước tiếp theo dựa trên context mới nhất.","o":{"A":"Lớp orchestration tự động định tuyến đến tool tiếp theo dựa trên trường status của đơn hàng.","B":"Agent tuân theo một decision tree được cấu hình sẵn, ánh xạ các thuộc tính của đơn hàng đến các tool call cụ thể.","C":"Chi tiết đơn hàng được thêm vào cuộc hội thoại và model suy luận (reasons) về hành động cần thực hiện.","D":"Agent thực thi các bước còn lại trong một chuỗi tool đã được lên kế hoạch từ đầu request."}},"37":{"q":"Một khách hàng gửi: \"Thật bực mình. Tôi đã giải thích vấn đề của mình hai lần rồi mà vẫn chưa được giải quyết. Tôi muốn nói chuyện với một người thật NGAY BÂY GIỜ.\" Agent chưa gọi bất kỳ tool nào để điều tra tài khoản của họ. Agent nên làm gì?","e":"Khách hàng đã nói \"hai lần\" nhưng bạn chưa có context nào cả. Một câu hỏi tập trung, thể hiện sự ghi nhận (acknowledging) cho bạn cơ hội giải quyết ngay từ lần liên hệ đầu tiên (first-contact resolution) mà không phớt lờ sự bực bội hay trì hoãn một khả năng chuyển tiếp (handoff). Việc lao vào liệt kê năng lực (capability-listing) (B) nghe có vẻ coi thường, việc chuyển tiếp (escalating) mà không có context tool nào (C) tạo ra một cuộc bàn giao lạnh lẽo (cold handoff) nơi con người cũng phải bắt đầu lại từ đầu, và việc điều tra mà không hỏi (D) làm tăng độ trễ và không tôn trọng yêu cầu của khách hàng.","o":{"A":"Thừa nhận sự bực bội và hỏi một câu hỏi có mục tiêu (targeted) để hiểu rõ vấn đề cụ thể trước khi escalate.","B":"Giải thích ngắn gọn về những gì agent có thể hỗ trợ và đề nghị giải quyết vấn đề nhanh chóng, chỉ escalate nếu khách hàng lặp lại yêu cầu.","C":"Gọi escalate_to_human ngay lập tức kèm theo lịch sử hội thoại.","D":"Gọi get_customer và lookup_order trước để thu thập bối cảnh tài khoản, sau đó escalate cho một human agent."}},"38":{"q":"Agent của bạn đang xử lý một tranh chấp hóa đơn (billing dispute). Sau khi gọi get_customer và lookup_order, nó xác định rằng tranh chấp liên quan đến một lỗi định giá khuyến mãi (promotional pricing error) cần có sự phê duyệt của quản lý — vượt quá cấp độ ủy quyền (authorization level) của agent. Quy trình nên xử lý việc chuyển tiếp giữa chừng (mid-process escalation) này như thế nào?","e":"Một bản tóm tắt có cấu trúc (structured brief) (ai, đơn hàng nào, vấn đề gì, tại sao vượt quá thẩm quyền) cho phép nhân viên con người tiếp nhận ngay lập tức — đó là mẫu hình chuyển tiếp giữa chừng (mid-process escalation pattern). Việc chỉ chuyển tiếp tin nhắn gốc (A) bỏ mất context đã thu thập được từ tool, việc cố xử lý khoản hoàn tiền dù sao (C) là cố ý vượt quá thẩm quyền, một vi phạm chính sách, và việc lưu trữ (persist) vào một cơ sở dữ liệu với một reference ID (D) thêm hạ tầng và một bước tra cứu bổ sung trong khi một bản tóm tắt có cấu trúc nội tuyến (inline) đơn giản và nhanh hơn.","o":{"A":"Gọi escalate_to_human chỉ với message gốc của khách hàng.","B":"Biên soạn một bản handoff có cấu trúc gồm thông tin khách hàng, thông tin đơn hàng, và vấn đề đã xác định trước khi gọi escalate_to_human.","C":"Vẫn thử hoàn tiền bằng process_refund, chỉ escalate nếu hệ thống từ chối giao dịch.","D":"Lưu trữ toàn bộ lịch sử hội thoại và tool response vào một database, sau đó gọi escalate_to_human kèm theo một reference ID."}},"39":{"q":"Một khách hàng nêu ra ba vấn đề riêng biệt trong một phiên (session): một câu hỏi về hoàn tiền (lượt 1-15), một câu hỏi về gói đăng ký (subscription) (lượt 16-30), và một cập nhật phương thức thanh toán (lượt 31-45). Ở lượt 48, khách hàng hỏi \"Chuyện gì đã xảy ra với khoản hoàn tiền của tôi?\" Cuộc hội thoại đang tiến gần đến giới hạn context. Chiến lược nào duy trì tốt nhất khả năng của agent trong việc giải quyết tất cả các vấn đề trong suốt phiên làm việc?","e":"Tóm tắt tiến triển (progressive summarization) nén các chủ đề ổn định đã được giải quyết trong khi vẫn giữ nguyên văn (verbatim) mạch (thread) đang hoạt động — đây là mẫu hình kinh điển cho các cuộc hội thoại dài, nhiều vấn đề gần giới hạn context. Một lớp context phụ (sidecar context layer) (A) thêm công sức kỹ thuật và không tự nhiên bảo toàn được mạch chuyện hội thoại, việc lấy lại dữ liệu (re-fetching) (B) giúp đảm bảo tính mới nhưng không giải quyết được vấn đề độ dài context, và một sliding window thuần túy (D) sẽ âm thầm loại bỏ vấn đề hoàn tiền (lượt 1-15) khỏi context, chính xác là điều khách hàng đang hỏi.","o":{"A":"Trích xuất và lưu trữ dữ liệu vấn đề có cấu trúc (order ID, số tiền, trạng thái) vào một lớp context riêng biệt.","B":"Dựa vào các MCP tool để fetch lại thông tin liên quan khi cần, mỗi khi khách hàng nhắc đến vấn đề trước đó.","C":"Tóm tắt các lượt trước thành một mô tả tường thuật (narrative), chỉ giữ nguyên toàn bộ message history cho vấn đề đang xử lý (active issue).","D":"Triển khai sliding window context chỉ giữ lại 30 lượt gần nhất."}},"40":{"q":"Khi triển khai MCP tool lookup_order của bạn, backend đôi khi trả về lỗi (ví dụ: \"Order not found\" hoặc các sự cố cơ sở dữ liệu tạm thời). Đâu là mẫu hình đúng để truyền đạt các lỗi này trở lại cho agent?","e":"Đây là mẫu hình được thiết kế của MCP: đặt văn bản lỗi vào trường content và đánh dấu isError=true. Claude thấy được cả cờ báo thất bại lẫn một thông báo dễ đọc để suy luận. Việc trả về các kết quả thành công rỗng (A) khiến agent nghĩ rằng không có dữ liệu nào tồn tại thay vì có gì đó đã sai, các exception không được bắt (uncaught exceptions) (C) phá vỡ giao thức tool và không cho mô hình gì để suy luận, và các trường \"status\" tùy biến (ad-hoc) (D) khác nhau giữa các tool mà không có cách diễn giải chuẩn, không như isError.","o":{"A":"Ghi log lỗi ở phía server và trả về một kết quả rỗng để tránh gây nhầm lẫn cho model","B":"Trả về error message trong nội dung tool result với cờ isError được đặt là true","C":"Ném (throw) một exception từ tool handler để agent framework có thể bắt (catch) và ghi log lại","D":"Trả về một response thành công (success) với trường \"status\" cho biết loại lỗi"}},"41":{"q":"Tool process_refund của bạn trả về hai loại lỗi: lỗi kỹ thuật (\"503 Service Unavailable\", \"Connection timeout\") mang tính tạm thời (5% số lần gọi), và lỗi nghiệp vụ (\"Order exceeds 30-day return window\", \"Item already refunded\") mang tính vĩnh viễn (12% số lần gọi). Dữ liệu giám sát cho thấy agent lãng phí 3-4 lượt retry cho các lỗi nghiệp vụ vốn không bao giờ có thể thành công. Hiện tại, cả hai loại lỗi đều chỉ trả về một thông điệp văn bản thuần túy cho Claude. Đâu là cách hiệu quả nhất để giảm số lần retry lãng phí trong khi vẫn cải thiện chất lượng phản hồi hướng tới khách hàng?","e":"Một cờ retryable báo cho Claude biết một cách xác định rằng \"đừng retry\", còn một thông điệp thân thiện với khách hàng đã được soạn sẵn giúp cải thiện câu trả lời gửi đi — giải quyết cả hai vấn đề cùng lúc. Việc dựa vào mô hình để phân tích (text-parse) các chuỗi lỗi (phương án B) là mong manh, một tool kiểm tra điều kiện đủ điều kiện (eligibility-check, phương án C) làm tăng thêm một vòng round-trip cho mọi lần hoàn tiền và vẫn không giúp gì khi process_refund thất bại vì lý do khác, còn việc giấu các lần retry bên trong tool (phương án D) có thể che khuất độ trễ (latency) và vẫn để lại lỗi nghiệp vụ dưới dạng chuỗi văn bản thuần túy.","o":{"A":"Trả về structured error responses với retryable: false cho các lỗi nghiệp vụ (business errors) kèm theo lời giải thích thân thiện với khách hàng để Claude sử dụng.","B":"Thêm các few-shot examples minh họa cách phân biệt lỗi có thể retry với lỗi không thể retry bằng cách phân tích (parse) nội dung văn bản của thông báo lỗi.","C":"Thêm một tool check_refund_eligibility phải được gọi trước process_refund để ngăn chặn vi phạm quy tắc nghiệp vụ (business rule).","D":"Triển khai logic tự động retry ở cấp độ tool chỉ cho các lỗi kỹ thuật, còn các lỗi nghiệp vụ được chuyển cho Claude mà không thực hiện retry."}},"42":{"q":"Agent của bạn đã gọi lookup_order nhiều lần trong khi điều tra các yêu cầu trả hàng của khách hàng. Mỗi phản hồi bao gồm hơn 40 trường (items, shipping details, payment info, status history). Kết quả từ các tool hiện chiếm phần lớn context của cuộc hội thoại. Khách hàng đề cập thêm hai đơn hàng nữa mà họ muốn thảo luận. Đâu là cách tiếp cận hiệu quả nhất trước khi thực hiện thêm các lần tra cứu?","e":"Giữ lại các trường quan trọng đối với tác vụ và loại bỏ phần còn lại — điều này giải quyết trực tiếp vấn đề context bị phình to trước khi thêm hai lần tra cứu nữa. Tóm tắt bằng văn xuôi (phương án B) làm mất độ chính xác đối với các trường mà mô hình có thể cần sau này (ngày tháng, số tiền chính xác), một vector database (phương án C) là hạ tầng quá nặng nề cho một vấn đề về bản chất chỉ là cắt tỉa dữ liệu (pruning), và việc tiếp tục mà không thay đổi gì (phương án D) không giải quyết được tình trạng phình to context, khiến nó tiến dần đến việc cạn kiệt context (context exhaustion).","o":{"A":"Chỉ trích xuất các trường liên quan đến việc trả hàng (items, purchase date, return window, status) từ mỗi tool response đơn hàng hiện có, loại bỏ các chi tiết rườm rà.","B":"Để model tạo ra một bản tóm tắt bằng ngôn ngữ tự nhiên cho các chi tiết chính của mỗi đơn hàng, thay thế các structured responses bằng mô tả dạng văn xuôi.","C":"Chuyển tất cả tool responses sang một vector database có semantic indexing, truy xuất các phần liên quan khi cuộc hội thoại tiếp diễn.","D":"Tiếp tục thực hiện các lookup bổ sung mà không sửa đổi context của tool output hiện có."}},"43":{"q":"Trong quá trình kiểm thử ban đầu của pipeline review tự động, bạn nhận thấy rằng các lượt review trên các PR lớn (hơn 50 file thay đổi) đôi khi mất hơn 20 phút và tốn 8-12 đô la mỗi lần chạy do các vòng lặp agentic (agentic loops) kéo dài — Claude đọc file, chạy các tool phân tích, và lặp lại nhiều lần. Đội của bạn cần mỗi lần gọi (invocation) phải dừng lại khi đạt đến một số lượng iteration cố định và một số tiền cố định, được thực thi bởi chính Claude Code chứ không phải bởi job runner bên ngoài. Thay đổi cấu hình nào sẽ trực tiếp áp đặt cả hai giới hạn trên mỗi lần gọi đó?","e":"Cờ --max-turns của Claude Code giới hạn số lượng vòng lặp agentic, còn --max-budget-usd giới hạn chi tiêu bằng đô la trên mỗi lần gọi, cả hai đều được thực thi tự nhiên bởi Claude Code ở chế độ headless (claude -p) — chính xác là hai giới hạn trên mỗi lần gọi được yêu cầu. Phương án C dựa vào job runner bên ngoài và việc giám sát dashboard một cách thụ động, điều mà câu hỏi đã loại trừ rõ ràng, trong khi phương án B chỉ giảm chi phí mà không áp đặt bất kỳ giới hạn nào, và phương án D quản lý quyền sử dụng tool (tool permissions), chứ không phải số iteration hay mức chi tiêu.","o":{"A":"Thêm --max-turns 10 --max-budget-usd 2.00 vào lệnh gọi claude -p để giới hạn số vòng lặp (iterations) và chi phí.","B":"Chuyển flag --model sang một model nhỏ hơn, rẻ hơn để mỗi iteration dùng ít token hơn và giảm chi phí mỗi lần gọi.","C":"Đặt timeout-minutes: 5 cho step của job trong GitHub Actions và theo dõi chi phí mỗi lần chạy qua usage dashboard trên Anthropic Console.","D":"Đặt --permission-mode dontAsk để tự động từ chối (auto-deny) mọi yêu cầu tool permission không nằm trong tập được cho phép rõ ràng."}},"44":{"q":"Việc sinh test tự động của bạn tạo ra các unit test cho code mới, nhưng các lượt review cho thấy 55% trong số đó có giá trị thấp: các assertion sơ sài chỉ kiểm tra hàm không throw exception, các test trùng lặp với phạm vi kiểm thử (coverage) đã có sẵn, hoặc các test bỏ qua các quy ước fixture của đội bạn. Làm thế nào để bạn giảm tỷ lệ các test có giá trị thấp được sinh ra ngay từ đầu?","e":"Câu hỏi hỏi rõ ràng làm thế nào để giảm các test có giá trị thấp \"ngay từ khi được sinh ra\", nghĩa là phải khắc phục nguyên nhân gốc rễ ở đầu nguồn: Claude thiếu bối cảnh (context) về việc đội của bạn coi thế nào là một test có giá trị. Việc ghi lại các tiêu chuẩn kiểm thử, cách dùng fixture, và các ví dụ tốt-so với-sơ sài trong CLAUDE.md cung cấp cho Claude bối cảnh đó ngay tại thời điểm sinh test, trong khi phương án A và D chỉ lọc bỏ kết quả xấu sau khi đã xảy ra, còn phương án B né tránh vấn đề thay vì giải quyết nó.","o":{"A":"Thêm bước phân tích coverage sau khi sinh (post-generation coverage analysis) để tự động lọc bỏ mọi test được sinh ra mà không làm tăng line coverage vượt quá mức các test hiện có đã cung cấp.","B":"Giới hạn việc sinh test (test generation) cho các thư mục mà các chỉ số chất lượng lịch sử (historical quality metrics) cho thấy tỷ lệ chấp nhận cao hơn, tắt tính năng này ở những khu vực mà test được sinh ra luôn cần chỉnh sửa nhiều.","C":"Ghi lại các tiêu chuẩn kiểm thử trong CLAUDE.md, bao gồm tiêu chí đánh giá test có giá trị, các fixtures sẵn có kèm mục đích sử dụng dự kiến, và các ví dụ phân biệt giữa test hành vi (behavioral test) có ý nghĩa với các assertion tầm thường.","D":"Triển khai quy trình sinh hai giai đoạn, trong đó một lệnh gọi Claude thứ hai chấm điểm từng test theo tiêu chí chất lượng, lọc bỏ các test điểm thấp trước khi trình bày kết quả cho developer."}},"45":{"q":"Hôm qua, một kỹ sư đã dùng Claude Code để điều tra các luồng xác thực (authentication flows) trong một hệ thống monolith cũ, tích lũy một lượng context đáng kể qua một phiên làm việc kéo dài 2 giờ. Hôm nay cô ấy muốn tiếp tục cuộc điều tra cụ thể đó. Cô ấy đã làm việc trên ba codebase khác kể từ đó và biết rằng phiên làm việc đó được đặt tên là \"auth-deep-dive\". Cô ấy nên tiếp tục như thế nào?","e":"Cờ --resume của Claude Code chấp nhận tên phiên hoặc ID, do đó --resume auth-deep-dive sẽ tải lại đúng phiên được đặt tên đó cùng toàn bộ context đã tích lũy. --continue chỉ tiếp tục cuộc hội thoại gần đây nhất, mà đó lại là một trong các phiên khác cô ấy đã làm việc kể từ đó, còn việc tự tìm kiếm thủ công một UUID hoặc bắt đầu lại từ đầu sẽ đánh mất giá trị của phiên đã được đặt tên.","o":{"A":"Dùng --continue để tiếp tục từ nơi cuộc hội thoại gần nhất đã dừng lại.","B":"Dùng --resume auth-deep-dive để tải phiên (session) cụ thể đó theo tên.","C":"Dùng --session-id với UUID lấy từ file transcript của session hôm qua.","D":"Bắt đầu lại từ đầu và đọc lại các file tương tự."}},"46":{"q":"Sau khi tích hợp một MCP server cục bộ cung cấp các tool phân tích code (analyze_dependencies, find_dead_code, calculate_complexity), bạn xác nhận rằng server hoạt động tốt (healthy) và các tool xuất hiện trong phản hồi tools/list. Tuy nhiên, bạn quan sát thấy agent luôn dùng Grep để tìm kiếm các câu lệnh import thay vì gọi analyze_dependencies — ngay cả khi người dùng hỏi rõ ràng về \"code dependencies\". Kiểm tra định nghĩa tool cho thấy: MCP: analyze_dependencies — \"Analyzes dependency graph\"; Built-in: Grep — \"Search file contents for a pattern using regular expressions. Returns matching lines with line numbers and surrounding context.\" Đâu là cách tiếp cận hiệu quả nhất để cải thiện việc lựa chọn tool MCP của agent?","e":"Nguyên nhân gốc rễ là sự bất cân xứng trong mô tả tool: mô tả mơ hồ \"Analyzes dependency graph\" của tool MCP thua kém so với mô tả chi tiết, cụ thể của Grep, nên agent chọn Grep. Các best practice về tool-use của Anthropic nói rằng mô tả tool là đòn bẩy chính cho việc lựa chọn tool — viết mô tả chi tiết về khả năng, kết quả đầu ra, và khi nào nên dùng tool sẽ khắc phục việc lựa chọn tại nguồn, trong khi việc loại bỏ Grep, chia nhỏ tool, hoặc thêm các quy tắc điều hướng system-prompt mong manh chỉ là các giải pháp tình thế.","o":{"A":"Loại bỏ Grep khỏi danh sách tool khả dụng khi MCP server được kết nối để loại bỏ sự chồng chéo về chức năng.","B":"Tách analyze_dependencies thành các tool nhỏ hơn, chi tiết hơn (list_imports, resolve_transitive_deps, detect_circular_deps) để mỗi tool có mục đích tập trung, ít có khả năng chồng chéo với Grep.","C":"Thêm hướng dẫn định tuyến (routing instructions) vào system prompt, chỉ rõ rằng các câu hỏi liên quan đến dependency nên dùng MCP tools thay vì Grep.","D":"Mở rộng mô tả (descriptions) của MCP tool để nêu chi tiết khả năng và đầu ra—ví dụ: \"Builds dependency graph showing direct imports, transitive dependencies, and cycles.\""}},"47":{"q":"Một kỹ sư yêu cầu agent tìm tất cả các nơi gọi (callers) một hàm trước khi xóa nó. Hàm này được định nghĩa trong một thư viện lõi (core library) nhưng cũng được expose qua các module wrapper đổi tên hàm cho mục đích sử dụng theo domain cụ thể (ví dụ: calculateTax trong thư viện trở thành computeOrderTax trong module orders). Chiến lược khám phá nào sẽ xác định các nơi gọi một cách đáng tin cậy nhất?","e":"Vì hàm này được re-export dưới các tên khác nhau bởi các module wrapper, việc chỉ grep tên gốc (phương án B) sẽ bỏ sót các nơi gọi qua tên bí danh (alias), còn tài liệu (documentation, phương án A) có thể đã lỗi thời hoặc không đầy đủ. Chiến lược đáng tin cậy là trước tiên đọc thư viện và các wrapper để liệt kê mọi tên/bí danh được expose, sau đó Grep từng tên trên toàn bộ codebase; phương án D là gián tiếp và tốn công hơn nhiều, đòi hỏi phải đọc thủ công mọi file có import hàm đó.","o":{"A":"Tìm kiếm tên function trong tài liệu dự án để hiểu các mẫu sử dụng dự kiến và điều hướng đến các điểm tích hợp đã được ghi lại.","B":"Dùng Grep để tìm kiếm tên gốc của function trên toàn bộ codebase.","C":"Đọc thư viện (library) và các wrapper module để xác định tất cả các tên được expose cho function, sau đó dùng Grep cho từng tên trên toàn bộ codebase.","D":"Dùng Grep để tìm tất cả các file import từ library hoặc wrapper module, sau đó đọc từng file để kiểm tra xem nó có sử dụng function đó hay không."}},"48":{"q":"Một subagent khám phá của kỹ sư đã dành 30 phút phân tích một hệ thống thanh toán cũ (legacy payment system), đọc 47 file và ghi lại các luồng dữ liệu (data flows). Phiên làm việc bị gián đoạn khi kết nối của kỹ sư bị rớt. Trong lúc vắng mặt, một đồng nghiệp đã merge một PR đổi tên hai hàm tiện ích (utility function). Kỹ sư muốn tiếp tục cuộc khám phá tương tự. Đâu là cách tiếp cận hiệu quả nhất?","e":"Việc tiếp tục (resume) từ transcript đã lưu giữ nguyên toàn bộ 30 phút context khám phá đã tích lũy (47 file, các luồng dữ liệu đã ghi lại) mà không phải tốn thêm token, và việc nói rõ cho agent biết về hai hàm tiện ích đã bị đổi tên chỉ sửa đúng phần kiến thức đã trở nên lỗi thời. Phương án D để agent tiếp tục hoạt động với tên hàm đã lỗi thời, phương án B nhồi nhét toàn bộ transcript vào một context window mới một cách lãng phí, còn phương án C bỏ đi sự hiểu biết chi tiết ở cấp độ file.","o":{"A":"Resume subagent từ transcript trước đó của nó và thông báo cho nó về các function đã đổi tên.","B":"Khởi chạy một subagent mới và đưa transcript trước đó vào initial prompt để làm ngữ cảnh (context).","C":"Khởi chạy một subagent mới kèm bản tóm tắt các phát hiện trước đó.","D":"Resume subagent từ transcript trước đó mà không đề cập đến các thay đổi—vì hiểu biết về kiến trúc (architecture) vẫn còn giá trị."}},"49":{"q":"Tình huống: Năng suất phát triển (Developer Productivity) — Agent của bạn đã dành 25 phút khám phá phân hệ rendering của một game engine — đọc shader code, quản lý buffer, và logic đồng bộ hóa frame (frame synchronization). Một kỹ sư giờ yêu cầu agent tìm hiểu cách physics engine tích hợp với rendering cho các lớp phủ debug va chạm (collision debug overlays). Bạn nhận thấy các phản hồi gần đây tham chiếu đến \"các mẫu rendering điển hình\" thay vì các lớp VulkanPipeline và FrameGraph cụ thể mà nó đã phát hiện trước đó. Đâu là cách tiếp cận hiệu quả nhất?","e":"Các phản hồi chung chung kiểu \"các mẫu rendering điển hình\" báo hiệu sự suy giảm context (context degradation) do phiên làm việc dài và cồng kềnh, vì vậy cách khắc phục là nén (compact) kiến thức rendering có giá trị thành một bản tóm tắt và giao nó cho một sub-agent với context mới hoàn toàn cho tác vụ physics. Cách này tuân theo best practice quản lý context của Anthropic là tóm tắt kết hợp với các sub-agent có context sạch, giữ lại các phát hiện cụ thể mà tác vụ tích hợp phụ thuộc vào, khác với phương án A (mất kiến thức), phương án B (sub-agent thiếu context cần thiết), hoặc phương án D (tiếp tục trong một context đã suy giảm).","o":{"A":"Dùng /clear để reset context hoàn toàn, sau đó bắt đầu lại từ đầu để khám phá phần physics bằng cách dùng các đường dẫn file từ CLAUDE.md của dự án.","B":"Spawn một sub-agent để khám phá phần physics một cách độc lập, sau đó tự tổng hợp thủ công các phát hiện của nó với kiến thức về rendering đã tích lũy trong cuộc hội thoại chính.","C":"Tóm tắt các phát hiện chính về rendering, sau đó spawn một sub-agent để khám phá physics với bản tóm tắt đó nằm trong initial context của nó.","D":"Tiếp tục trong context hiện tại với các prompt nhắm mục tiêu cụ thể hơn, tham chiếu trực tiếp đến tên các class cụ thể."}},"50":{"q":"Một kỹ sư yêu cầu agent tìm hiểu cách lớp caching hoạt động trước khi thêm một trigger vô hiệu hóa cache (cache invalidation) mới. Sau các lần tìm kiếm Grep ban đầu, agent đã xác định rằng logic caching trải rộng trên 15 file bao gồm decorator, middleware, và các lớp service (tổng cộng khoảng 8.000 dòng). Đâu là bước tiếp theo hiệu quả nhất để xây dựng sự hiểu biết trong khi vẫn quản lý các ràng buộc về context?","e":"Bắt đầu từ lớp cache cơ sở (base cache class) cho agent nắm được sự trừu tượng hóa (abstraction) và interface cốt lõi mà cả 15 file đều dựa trên đó, sau đó chỉ theo dấu các phần triển khai invalidation liên quan sẽ mang lại sự hiểu biết cấu trúc sâu sắc với mức sử dụng context tối thiểu. Đọc tất cả các file (phương án B) lãng phí context, ưu tiên theo kích thước file (phương án A) là tùy tiện, còn đọc theo dải dòng chỉ dựa trên từ khóa (phương án C) tạo ra kiến thức rời rạc, không đủ để thêm một trigger invalidation mới một cách an toàn.","o":{"A":"Dùng Glob để tìm các file khớp với các mẫu caching phổ biến (cache.py, caching/), ưu tiên đọc các file lớn nhất trước, sau đó kiểm tra các file nhỏ hơn để tìm những phần còn thiếu.","B":"Dùng tool Read để tải tuần tự cả 15 file, xây dựng hiểu biết đầy đủ về toàn bộ phần triển khai (implementation) caching.","C":"Dùng Grep để tìm kiếm các mẫu \"invalidate\" và \"expire\" trên tất cả các file, sau đó chỉ Read những dải dòng (line range) cụ thể đó với rất ít ngữ cảnh xung quanh.","D":"Phân tích import và class hierarchy để xác định base cache class, Read file đó để hiểu interface, sau đó truy vết các phần triển khai invalidation cụ thể."}},"51":{"q":"Agent của bạn đã phân tích một module service phức tạp — đọc 23 file mã nguồn, theo dấu các luồng request, và xác định các mẫu xử lý lỗi. Một nhà phát triển muốn so sánh hai chiến lược kiểm thử trước khi quyết định chọn một: end-to-end test với các dịch vụ ngoài được mock so với snapshot test ghi lại kết quả đầu ra kỳ vọng. Họ cần phát triển độc lập cả hai cách tiếp cận để đánh giá sự đánh đổi (trade-offs). Bạn nên quản lý các phiên làm việc như thế nào?","e":"Tiếp tục (resume) phiên phân tích bằng fork_session (CLI --fork-session / Agent SDK fork_session=True kèm resume) sẽ phân nhánh phiên làm việc thành các session ID mới trong khi vẫn giữ nguyên toàn bộ context phân tích và để phiên gốc không bị ảnh hưởng. Việc fork hai lần cho mỗi chiến lược kiểm thử toàn bộ phân tích 23 file mà không phải làm lại, và hai nhánh phát triển hoàn toàn độc lập với nhau — đúng như yêu cầu đã nêu. Xuất ra file (export) làm mất dữ liệu, các phiên mới hoàn toàn bỏ đi phần phân tích, còn một phiên tuần tự duy nhất thì không độc lập cũng không khách quan (unbiased).","o":{"A":"Xuất các phát hiện chính của session phân tích ra một file, sau đó tạo hai session mới cùng tham chiếu đến file này.","B":"Resume session phân tích với fork_session được bật, tạo một nhánh (branch) riêng cho mỗi chiến lược kiểm thử (testing strategy).","C":"Bắt đầu hai session mới, mỗi session tự đọc lại các file mã nguồn liên quan trước khi bắt đầu.","D":"Tiếp tục trong session ban đầu, phát triển end-to-end test trước, sau đó phát triển snapshot test tuần tự."}},"52":{"q":"Tình huống: Năng suất phát triển (Developer Productivity). Công cụ khám phá codebase của bạn lưu trữ các session ID để cho phép kỹ sư tiếp tục các cuộc điều tra qua nhiều phiên làm việc. Một kỹ sư đã dành một giờ hôm qua để phân tích một module xác thực (authentication) cũ, xây dựng context về kiến trúc và các phụ thuộc (dependencies) của nó. Họ muốn tiếp tục hôm nay. Session ID vẫn còn hợp lệ, nhưng hệ thống quản lý phiên bản (version control) cho thấy 3 trong số 12 file mà agent đã đọc trước đó đã bị một đồng nghiệp sửa đổi qua đêm khi merge. Cách tiếp cận nào cân bằng tốt nhất giữa hiệu quả và độ chính xác?","e":"Tiếp tục (resume) phiên làm việc giữ nguyên một giờ context đã tích lũy về kiến trúc của module (hiệu quả), trong khi nói rõ cho agent biết chính xác 3 file nào đã thay đổi cho phép đọc lại có mục tiêu chỉ đúng những file đã lỗi thời (độ chính xác). Đọc lại toàn bộ 12 file (phương án A) lãng phí token, bắt đầu lại từ đầu (phương án B) bỏ đi context có giá trị, còn resume một cách âm thầm (phương án D) có nguy cơ khiến agent hành động dựa trên nội dung file đã lỗi thời.","o":{"A":"Resume session và lập tức yêu cầu agent đọc lại toàn bộ 12 file đã được phân tích trước đó.","B":"Bắt đầu một session mới để đảm bảo agent làm việc với trạng thái codebase hiện tại mà không có các giả định (assumptions) đã lỗi thời.","C":"Resume session và thông báo cho agent biết những file cụ thể nào đã thay đổi để phân tích lại có mục tiêu (targeted re-analysis).","D":"Resume session mà không thông báo cho agent về các file đã thay đổi."}},"53":{"q":"Trong quá trình kiểm thử, bạn quan sát thấy rằng trong các phiên khám phá kéo dài (hơn 30 phút), agent bắt đầu đưa ra các câu trả lời thiếu nhất quán về cấu trúc code đã được thảo luận trước đó. Các kỹ sư báo cáo rằng họ phải nhắc lại context về các module mà họ đã khám phá rồi. Đâu là cách tiếp cận hiệu quả nhất để giải quyết vấn đề này?","e":"Một scratchpad đưa các phát hiện ra lưu trữ bền vững (durable storage) mà agent có thể đọc lại theo yêu cầu, cho nó một \"bộ nhớ\" ổn định không phụ thuộc vào mức độ chật chội của context window. Một context window lớn hơn (phương án B) chỉ trì hoãn vấn đề chứ không giải quyết được sự suy giảm chú ý (attention degradation) qua các context dài và nhiễu, việc xóa toàn bộ (wholesale clearing, phương án C) bỏ đi các phát hiện hợp lệ, còn tóm tắt trước (pre-summaries, phương án D) làm mất chi tiết và thường trình bày sai lệch các file mà kỹ sư quan tâm nhất.","o":{"A":"Để agent duy trì một file scratchpad ghi lại các phát hiện chính, và tham chiếu đến file đó cho các câu hỏi tiếp theo.","B":"Chuyển sang một model tier có năng lực cao hơn để có nhiều không gian context window hơn cho dữ liệu khám phá đã tích lũy.","C":"Triển khai việc tự động xóa context (context clearing) mỗi 15 phút để đảm bảo agent luôn bắt đầu với context mới, không bị nhiễu.","D":"Tạo bản tóm tắt cho tất cả các file mã nguồn trước khi bắt đầu khám phá, chỉ tải các bản trình bày đã được nén (compressed representations) này vào context."}},"54":{"q":"Hôm qua một kỹ sư đã dùng agent để phân tích một module xác thực (authentication) cũ, xác định hai cách tiếp cận tái cấu trúc (refactoring) khác nhau: tách thành một microservice so với tái cấu trúc tại chỗ (in-place). Hôm nay, họ muốn khám phá sâu cả hai cách tiếp cận — để agent đề xuất các thay đổi code cụ thể cho từng cách — trước khi quyết định triển khai cách nào. Đâu là cách hiệu quả nhất để cấu trúc cuộc khám phá này?","e":"Fork từ phiên làm việc của hôm qua cho mỗi cách tiếp cận một context độc lập riêng, bắt đầu từ cùng một nền tảng phân tích (analysis baseline) — sạch sẽ, song song, không lẫn lộn. Tái tạo thủ công (phương án A) dễ sai sót và làm mất trạng thái làm việc chính xác, bắt đầu lại từ đầu trong hai phiên (phương án B) làm lại công việc và có nguy cơ lệch khỏi cùng một nền tảng, còn khám phá tuần tự trong một luồng duy nhất (phương án C) khiến mỗi cách tiếp cận làm lẫn lộn context của cách kia.","o":{"A":"Resume session của hôm qua để khám phá cách tiếp cận thứ nhất, sau đó bắt đầu một session mới cho cách tiếp cận thứ hai, tự tái tạo lại context ban đầu theo cách thủ công.","B":"Bắt đầu hai session mới, tự cung cấp bản tóm tắt các phát hiện phân tích của hôm qua theo cách thủ công để thiết lập context.","C":"Resume session của hôm qua và khám phá cả hai cách tiếp cận tuần tự trong cùng một luồng hội thoại (conversation thread).","D":"Dùng fork_session để tạo hai nhánh (branches) từ phân tích của hôm qua, khám phá mỗi cách tiếp cận trong một nhánh riêng."}},"55":{"q":"Một kỹ sư yêu cầu agent của bạn xác định các đường dẫn code chưa được kiểm thử (untested code paths) trong một module xử lý thanh toán cũ trải rộng trên 45 file. Sau khi đọc 8 file mã nguồn đầu tiên, các phản hồi của agent trở nên kém chính xác rõ rệt — nó quên các mẫu code đã thảo luận trước đó và vẫn chưa xác định hết các file test hoặc theo dấu các luồng thanh toán quan trọng. Đâu là cách tiếp cận hiệu quả nhất để hoàn thành cuộc điều tra này?","e":"Giao các cuộc điều tra có phạm vi rõ ràng cho các subagent với context mới, trong khi agent chính giữ lại cái nhìn tổng quan về kiến trúc — đây là mẫu hình để mở rộng quy mô khám phá vượt ra ngoài một context window đơn lẻ. Một báo cáo duy nhất (phương án A) trở thành nguồn thông tin duy nhất và có xu hướng nén mất các mẫu code cụ thể, scratchpad kèm reset /clear hoàn toàn (phương án C) vẫn bỏ đi sự hiểu biết đã xây dựng qua 8 file, còn tìm kiếm chỉ bằng Grep (phương án D) không thể xác định các đường dẫn chưa được kiểm thử mà không đọc đủ mỗi đường dẫn để biết các nhánh nào test chưa bao phủ.","o":{"A":"Ghi lại toàn bộ các phát hiện hiện tại vào một báo cáo tóm tắt, xóa context hoàn toàn, sau đó dùng báo cáo đó làm tài liệu tham chiếu duy nhất để tiếp tục điều tra.","B":"Spawn các subagent để điều tra các câu hỏi cụ thể (ví dụ: \"find all test files for payment processing\", \"trace refund flow dependencies\") trong khi agent chính điều phối các phát hiện và duy trì hiểu biết tổng quan (high-level understanding).","C":"Xóa context bằng /clear, sau đó chọn lọc đọc lại chỉ những file quan trọng nhất đã phát hiện được cho đến nay, ghi các phát hiện chính vào một file scratchpad tồn tại xuyên suốt giữa các lần reset context.","D":"Chuyển sang dùng Grep để tìm kiếm tên function cụ thể thay vì đọc toàn bộ file, giảm lượng nội dung được tải vào context cho phần khám phá còn lại."}},"56":{"q":"Một nhà phát triển yêu cầu agent điều tra tại sao một API endpoint cụ thể thỉnh thoảng trả về lỗi 500. Codebase có hơn 200 file và nhà phát triển không biết những thành phần nào có liên quan. Agent phải theo dấu lỗi qua routing, middleware, logic nghiệp vụ, và các lớp cơ sở dữ liệu. Cách tiếp cận phân rã tác vụ (task decomposition) nào sẽ hiệu quả nhất?","e":"Debug về bản chất mang tính thích ứng (adaptive) — mỗi file bạn đọc sẽ thay đổi bước tiếp theo hữu ích nhất, vì vậy hãy để agent đi theo bằng chứng. Bạn không thể xây dựng một kế hoạch đúng cho một lỗi chưa rõ nguyên nhân mà không cần khám phá (phương án A), một pipeline cố định (phương án C) lãng phí công sức vào các lớp không liên quan và có thể khóa agent khỏi con đường tìm ra nguyên nhân gốc rễ thực sự, còn phân tán song song (fan-out, phương án D) hữu ích khi bạn đã có các tác vụ con có phạm vi rõ ràng, nhưng ở đây bạn sẽ phải trả gấp 4 lần chi phí để tìm kiếm ở ba lớp không phải là vấn đề.","o":{"A":"Để agent trước tiên tạo một kế hoạch toàn diện ánh xạ (mapping) tất cả các code path đi qua endpoint trước khi bắt đầu bất kỳ việc khám phá file hay đọc code nào.","B":"Để agent tự động sinh ra các investigation subtask theo cách động, dựa trên những gì nó phát hiện ở mỗi bước, điều chỉnh kế hoạch khám phá khi có thông tin mới về error path xuất hiện.","C":"Xác định trước một chuỗi bước điều tra cố định—grep tìm mẫu lỗi, sau đó đọc error handler, sau đó kiểm tra database query, sau đó xem xét middleware—thực hiện từng bước bất kể các phát hiện ở giữa chừng là gì.","D":"Chạy các worker agent song song, đồng thời điều tra cả bốn lớp (layer), sau đó tổng hợp các phát hiện của chúng để xác định lỗi bắt nguồn từ đâu."}},"57":{"q":"Sau khi thêm một MCP server với các tool tái cấu trúc (refactoring) code chuyên biệt (extract_function, rename_variable, inline_function), bạn nhận thấy agent vẫn dùng thao tác văn bản cơ bản qua Write và các lệnh Bash sed cho các tác vụ tái cấu trúc. MCP server đã được kết nối và hoạt động tốt (healthy). Kiểm tra cấu hình, bạn thấy mỗi tool MCP có một mô tả tối giản như \"extract_function: extracts a function from code.\" Đâu là cách hiệu quả nhất để cải thiện việc áp dụng các tool tái cấu trúc MCP?","e":"Việc lựa chọn tool được dẫn dắt bởi các mô tả mà Claude nhìn thấy. Khi các tool MCP nói \"extracts a function from code\" còn Write/sed đi kèm tài liệu phong phú hơn, Claude sẽ chọn Write/sed — nâng cấp các mô tả sẽ khắc phục nguyên nhân gốc rễ. Một bộ phân loại sơ bộ (pre-classifier, phương án A) là một hệ thống riêng cần duy trì và có thể định tuyến sai, việc loại bỏ các tool tổng quát (phương án B) ép buộc việc áp dụng bằng cách cắt giảm và phá vỡ các trường hợp sử dụng hợp lệ, còn việc chấp nhận thỏa hiệp (phương án C) đánh mất mục đích tích hợp các tool tái cấu trúc khi vấn đề thực sự nằm ở các mô tả.","o":{"A":"Triển khai một request classifier phát hiện ý định refactoring và tự động định tuyến các yêu cầu đó đến MCP server trước khi agent xử lý chúng.","B":"Loại bỏ tool Write khỏi cấu hình (configuration) của agent cho các phiên refactoring để nó buộc phải dùng MCP tools cho việc sửa đổi code.","C":"Chấp nhận đây là hành vi như mong đợi vì các tool đơn giản như sed dễ dự đoán hơn các tool refactoring chuyên biệt.","D":"Cải thiện các mô tả (descriptions) của MCP tool để giải thích khi nào mỗi tool nên được ưu tiên hơn thao tác chỉnh sửa văn bản (text manipulation), và làm rõ input và output mong đợi."}},"58":{"q":"Agent của bạn cần chèn một hàm hỗ trợ (helper function) mới vào giữa một module tiện ích 150 dòng, giữa hai hàm hiện có. Tool Edit thất bại vì tham số old_string của nó không thể tìm thấy văn bản duy nhất để khớp — file có các docstring, tên biến, và mẫu cấu trúc lặp lại. Đâu là cách đáng tin cậy nhất để hoàn thành việc chèn này?","e":"Khi hợp đồng khớp duy nhất (unique-match contract) của Edit không thể được thỏa mãn trong một file lặp lại, hãy chuyển sang dùng Read, chỉnh sửa trong bộ nhớ tại đúng dòng mong muốn, rồi Write toàn bộ file trở lại. Các chuỗi khớp dài, mong manh (phương án A) thường bị trượt do khoảng trắng hoặc các chỉnh sửa nhỏ, replace_all (phương án B) sẽ làm biến đổi mọi lần xuất hiện của mẫu đó và làm hỏng toàn bộ file, còn việc thêm vào cuối (append, phương án C) đặt hàm sai vị trí vì yêu cầu là chèn nó giữa hai hàm hiện có.","o":{"A":"Dùng Edit với một old_string cực dài, chứa hơn 30 dòng ngữ cảnh để đảm bảo tính duy nhất (uniqueness).","B":"Dùng tham số replace_all của Edit để nhắm vào một mẫu (pattern) phổ biến và nhúng function mới vào trong văn bản thay thế (replacement text).","C":"Dùng Bash để nối thêm (append) định nghĩa function vào cuối file bằng cú pháp heredoc.","D":"Dùng Read để tải file, thêm function vào vị trí thích hợp, sau đó dùng Write để ghi lại file đã cập nhật."}},"59":{"q":"Một kỹ sư vừa gia nhập đội yêu cầu agent giúp họ hiểu kiến trúc xác thực (authentication) và phân quyền (authorization) trước khi thực hiện các cải tiến bảo mật. Codebase có hơn 800 file trên nhiều dịch vụ. Chiến lược khám phá nào sẽ xây dựng sự hiểu biết hiệu quả nhất, xét đến các tool tích hợp sẵn của Claude và giới hạn context?","e":"Bắt đầu từ các điểm vào (entry points) (đăng nhập, xác minh token, middleware), sau đó theo dấu ra ngoài bám theo các cạnh code thực tế — dần dần, có căn cứ, và nằm trong giới hạn context. Kỹ sư vừa mới gia nhập (phương án A) và có khả năng chưa biết file nào quan trọng — đó chính là điều mà agent được kỳ vọng giúp đỡ. Không biết auth nằm ở đâu, việc phân tán song song (fan-out, phương án B) khám phá quá rộng và trùng lặp hoặc bỏ sót các luồng xuyên dịch vụ, còn việc đọc theo từ khóa trên diện rộng (phương án D) sẽ chạm phải một lượng lớn code không liên quan trên hơn 800 file và nhấn chìm context trong nhiễu.","o":{"A":"Đọc mọi file CLAUDE.md và README trước, sau đó hỏi kỹ sư (engineer) chỉ rõ 10-15 file nào là quan trọng nhất để hiểu hệ thống auth.","B":"Khởi chạy các subagent song song để khám phá các service khác nhau đồng thời, sau đó tổng hợp các phát hiện của chúng thành một bản tổng quan kiến trúc (architectural overview).","C":"Dùng Grep để tìm các entry point của authentication, đọc các file đó, sau đó theo dõi import và function call để dần dần vẽ ra (map) luồng auth.","D":"Đọc tất cả các file có chứa \"auth\", \"login\", \"permission\", hoặc \"token\" trong nội dung hoặc tên file."}},"60":{"q":"Một lỗi nghiêm trọng đang ảnh hưởng đến người dùng production. Nhật ký lỗi (error logs) cho thấy các exception trong module OrderProcessing với một stack trace rõ ràng chỉ thẳng vào một khu vực cụ thể, nhưng bạn chưa từng làm việc với module này trước đây. Đâu là cách tiếp cận hiệu quả nhất?","e":"Debug mang tính thích ứng (adaptive) — mỗi file bạn đọc sẽ thay đổi bước tiếp theo hữu ích nhất, vì vậy hãy để agent đi theo bằng chứng. Stack trace đã chỉ thẳng vào điểm thất bại, nên việc thực thi trực tiếp (đọc trace, đọc code liên quan, sửa lỗi ngay khi xác định được nguyên nhân gốc rễ) là con đường nhanh nhất và đáng tin cậy nhất. Lập kế hoạch trước khi khám phá bất kỳ lỗi chưa rõ nguyên nhân nào (phương án A) lãng phí thời gian và dễ bỏ lỡ đường dẫn thất bại thực sự, một bước plan-mode bổ sung (phương án B) là không cần thiết cho một lỗi đã được khoanh vùng sẵn, còn khám phá toàn bộ kiến trúc (phương án D) là khám phá thừa thãi khi stack trace đã xác định chính xác vị trí.","o":{"A":"Dùng plan mode để phân tích lỗi trong bối cảnh thiết kế của module, liệt kê các nguyên nhân gốc (root cause) tiềm ẩn, và ưu tiên các hướng khắc phục một cách có hệ thống.","B":"Bắt đầu bằng cách thực thi trực tiếp (direct execution) để thu thập thông tin ban đầu, sau đó chuyển sang plan mode để thiết kế một giải pháp toàn diện trước khi triển khai.","C":"Dùng direct execution để xem xét stack trace, đọc code liên quan, và triển khai bản sửa lỗi (fix) ngay khi xác định được root cause.","D":"Vào plan mode để khám phá kiến trúc (architecture) và dependency của module trước khi thử bất kỳ cách khắc phục nào."}},"61":{"q":"Sau khi triển khai review tự động, bạn nhận thấy precision cao nhưng recall thấp — các bug thật đang lọt qua mà không bị phát hiện. Điều tra cho thấy prompt review của bạn hướng dẫn Claude \"chỉ báo cáo các vấn đề có độ tin cậy cao mà bạn chắc chắn\" và \"thiên về việc không comment\". Các developer đánh giá cao mức độ nhiễu thấp, nhưng một race condition từng gây ra sự cố production đã xuất hiện trong một PR được review nhưng không được báo cáo. Bạn cần cải thiện đáng kể khả năng phát hiện bug trong khi vẫn giữ tỷ lệ false positive ở mức chấp nhận được đối với team của bạn. Đâu là cách tiếp cận hiệu quả nhất?","e":"Hướng dẫn code review của Anthropic cho các model Claude gần đây nêu rõ rằng chỉ thị \"chỉ báo cáo các vấn đề có độ tin cậy cao\" được tuân theo một cách rất sát nghĩa đen và làm giảm recall, đồng thời khuyến nghị nói với Claude báo cáo mọi finding kèm theo confidence và severity metadata, trong khi việc filtering được chuyển sang một giai đoạn verification/thresholding riêng ở downstream. Phương án D chính là mẫu hình hai giai đoạn \"bao phủ rồi mới lọc theo ngưỡng\" (coverage-then-threshold) này; B vẫn giữ lại bộ lọc làm giảm recall, C không giải quyết chỉ thị filtering, và cách chặn thẳng theo category ở A có thể vô tình tiếp tục che giấu các bug thật và thiếu confidence/severity metadata cần thiết để filtering một cách có nguyên tắc.","o":{"A":"Loại bỏ các hướng dẫn lọc thận trọng và yêu cầu Claude báo cáo mọi vấn đề tiềm ẩn, sau đó áp dụng một bộ lọc lập trình (programmatic filter) để loại bỏ trùng lặp và ẩn các danh mục vốn thường tạo ra false positive trong lịch sử.","B":"Thêm các few-shot example chi tiết minh họa các danh mục lỗi mà Claude nên gắn cờ — race condition, null dereference, các lỗ hổng trong xử lý lỗi — trong khi vẫn giữ hướng dẫn lọc high-confidence để duy trì mức độ chính xác (precision) hiện tại.","C":"Mở rộng context window bằng cách đưa vào các test file liên quan, lịch sử git gần đây, và dependency graph của module cùng với diff, giúp Claude có thêm tín hiệu phong phú hơn để đánh giá mức độ nghiêm trọng của vấn đề.","D":"Chia review thành một giai đoạn phát hiện (finding stage) trong đó mục tiêu của Claude là độ bao phủ (coverage) — gắn cờ mọi vấn đề tiềm ẩn kèm metadata về confidence và severity — và một giai đoạn riêng biệt để áp ngưỡng (threshold) cho các phát hiện đó."}},"62":{"q":"Hệ thống extraction của bạn xử lý hai loại tài liệu: báo cáo hàng tháng tiêu chuẩn (được lưu trữ sau khi xử lý) và báo cáo ngoại lệ khẩn cấp (phải kích hoạt cảnh báo nghiệp vụ trong vòng 30 phút kể từ khi nhận). Cả hai đều dùng chung một JSON schema. Bạn muốn giảm thiểu chi phí API trong khi vẫn đáp ứng yêu cầu về latency. Bạn nên thiết kế kiến trúc pipeline xử lý như thế nào?","e":"Hãy khớp latency profile với mức độ khẩn cấp của tài liệu: dùng batch cho phần lớn tài liệu (rẻ), dùng real-time cho các exception nhạy cảm về latency (nhanh) — cách này giảm thiểu chi phí trong khi vẫn đáp ứng SLA. Định tuyến mọi thứ qua real-time (A) thì nhất quán nhưng tốn kém cho những tài liệu không cần đến điều đó, cửa sổ xử lý lên đến 24 giờ của Batch API (B) không thể đáp ứng SLA cảnh báo 30 phút cho các exception, và việc chạy batch theo giờ (C) vẫn phụ thuộc vào SLO của batch và không đảm bảo được khung thời gian 30 phút.","o":{"A":"Gửi tất cả tài liệu tới Messages API thời gian thực để đảm bảo độ trễ xử lý nhất quán giữa các loại tài liệu.","B":"Gửi tất cả tài liệu tới Batch API kèm theo custom_ids để theo dõi. Khi kết quả trả về, xử lý ngay các tài liệu khẩn cấp và kích hoạt cảnh báo trễ cho các ngoại lệ.","C":"Đưa tất cả tài liệu vào hàng đợi và gửi theo lô hàng giờ, gắn cờ các tài liệu khẩn cấp để xử lý ưu tiên khi kết quả batch trả về.","D":"Định tuyến các báo cáo tiêu chuẩn tới Batch API để tiết kiệm 50% chi phí, và định tuyến các báo cáo ngoại lệ khẩn cấp tới Messages API thời gian thực."}},"63":{"q":"Schema của bạn có một field skills: string[]. Giám sát production cho thấy ba vấn đề về tính nhất quán: (1) các cụm từ ghép như \"Python and SQL\" đôi khi được giữ nguyên là một entry, đôi khi bị tách ra; (2) các kỹ năng được ngụ ý nhưng không được nêu rõ đôi khi vẫn xuất hiện trong kết quả extraction; (3) các tài liệu tương tự nhau lại cho ra độ dài mảng khác nhau rất nhiều (5-10 so với hơn 40 entry). Prompt hiện tại của bạn ghi \"Extract all skills mentioned.\" Cải tiến nào là hiệu quả nhất?","e":"Cả ba vấn đề đều xoay quanh cách model diễn giải thế nào được tính là \"một kỹ năng\". Few-shot examples dạy cho model mẫu hình một cách cụ thể — tách hay không tách, được nêu rõ hay chỉ được suy luận, mức độ chi tiết (granularity) phù hợp. Việc giới hạn cứng số lượng (B) mang tính tùy tiện và có thể buộc phải bỏ sót các kỹ năng thật hoặc bịa ra để lấp đầy, post-processing (C) không thể sửa được các kỹ năng chỉ được suy luận chứ không được nêu rõ, cũng như không thể chọn đúng cách tách cho các cụm từ ghép, còn enriched metadata (D) là một tín hiệu hữu ích nhưng không giải quyết sự thiếu nhất quán từ gốc tại thời điểm extraction.","o":{"A":"Thêm các few-shot example minh họa cách xử lý cụm từ ghép, tiêu chí đề cập rõ ràng, và mức độ chi tiết (granularity) phù hợp cho mỗi entry.","B":"Thêm các ràng buộc: \"Trích xuất tối đa 10-20 kỹ năng, mỗi entry một kỹ năng, chỉ những kỹ năng được nêu tên rõ ràng.\"","C":"Thêm bước chuẩn hóa sau khi trích xuất (post-extraction normalization) để ánh xạ các kỹ năng vào một hệ phân loại (taxonomy) chuẩn và loại bỏ các entry tương tự trùng lặp.","D":"Bổ sung schema thành {skill: string, confidence: float, source_quote: string}[] để nắm bắt metadata trích xuất."}},"64":{"q":"Hệ thống của bạn đã vận hành với 100% human review trong 3 tháng. Phân tích cho thấy các extraction có model confidence >90% có độ chính xác tổng thể là 97%. Để giảm khối lượng công việc cho reviewer, bạn dự định tự động hóa các extraction có confidence cao. Trước khi triển khai, bước validation nào là quan trọng nhất?","e":"Độ chính xác tổng hợp (aggregate accuracy) che giấu các lỗi theo từng phân khúc (segment) — một loại tài liệu có thể chỉ đạt 70% trong khi các loại khác đạt 99%. Việc tự động định tuyến chỉ dựa trên con số tổng thể có nguy cơ gây ra lỗi hệ thống ở các phân khúc yếu. Việc điều chỉnh threshold (B) đáng để làm, nhưng chỉ nên thực hiện sau khi đã kiểm chứng độ chính xác theo từng segment; chạy pilot (C) là một thực hành tốt nhưng diễn ra sau bước phân tích segment; và việc xác minh rằng 97% đáp ứng yêu cầu (D) giả định rằng con số này đúng ở mọi nơi — trong khi đó chính là điều mà phân tích theo segment kiểm tra trước tiên.","o":{"A":"Phân tích độ chính xác theo loại tài liệu và theo từng field để xác nhận rằng các trích xuất high-confidence hoạt động nhất quán trên mọi phân khúc, chứ không chỉ ở mức tổng hợp.","B":"So sánh độ chính xác ở các ngưỡng confidence khác nhau (85%, 90%, 95%) để tìm ra điểm cắt tối ưu giúp tối đa hóa mức độ tự động hóa trong khi giảm thiểu sai sót.","C":"Chạy thử nghiệm thí điểm (pilot) trong hai tuần, định tuyến 25% các trích xuất high-confidence trực tiếp tới các hệ thống downstream và theo dõi báo cáo lỗi.","D":"Xác nhận rằng độ chính xác 97% đáp ứng yêu cầu của tất cả các hệ thống downstream sử dụng dữ liệu được trích xuất."}},"65":{"q":"Pipeline extraction của bạn xử lý các hợp đồng thường xuyên có kèm theo amendment (điều khoản sửa đổi). Khi một hợp đồng chứa cả điều khoản gốc lẫn các amendment sau đó (ví dụ: điều khoản gốc quy định \"30-day payment terms\" trong khi Amendment 1 thay đổi thành \"45 days\"), model trích xuất không nhất quán một trong hai giá trị mà không có chỉ dẫn nào cho biết giá trị nào đang có hiệu lực. Đâu là cách tiếp cận hiệu quả nhất để cải thiện độ chính xác extraction cho các tài liệu có amendment?","e":"Về bản chất cấu trúc, amendment liên quan đến các giá trị được version hóa (versioned values). Một schema gồm value + source location + effective date mô hình hóa đúng domain này và không còn buộc model phải chọn một trong hai. Các hệ thống downstream đôi khi vẫn cần đến giá trị gốc (B), vì vậy việc mã hóa cứng quy tắc \"bản mới nhất luôn thắng\" sẽ loại bỏ mất thông tin đó; một classifier loại bỏ các phần nội dung (C) có thể vô tình cắt bỏ nội dung vẫn còn hiệu lực pháp lý; còn việc định tuyến mọi hợp đồng có amendment đến con người (D) vừa tốn kém vừa vẫn không cho các hệ thống downstream một câu trả lời có cấu trúc.","o":{"A":"Thiết kế lại schema sao cho các field bị sửa đổi (amended) có thể nắm bắt nhiều giá trị, mỗi giá trị kèm theo vị trí nguồn (source location) và ngày hiệu lực (effective date).","B":"Thêm hướng dẫn vào prompt để luôn trích xuất giá trị sửa đổi (amendment) gần nhất và bỏ qua các điều khoản gốc đã bị thay thế.","C":"Tiền xử lý (preprocess) tài liệu bằng một bộ phân loại (classifier) để nhận diện và loại bỏ các phần đã bị thay thế trước bước trích xuất chính.","D":"Triển khai bước xác thực sau trích xuất (post-extraction validation) sử dụng khớp mẫu (pattern matching) để phát hiện các sửa đổi và gắn cờ những trích xuất đó để con người xem xét thủ công."}},"66":{"q":"Hệ thống extraction của bạn triển khai cơ chế tự động retry khi validation thất bại. Ở mỗi lần retry, lỗi validation cụ thể được thêm vào prompt. Cách tiếp cận retry-with-error-feedback này giải quyết được hầu hết các lỗi trong vòng 2-3 lần thử. Với mẫu lỗi (failure pattern) nào thì việc retry thêm sẽ ÍT hiệu quả nhất?","e":"Dù retry bao nhiêu lần cũng không thể dạy cho model thông tin vốn không có trong input. Retry-with-error-feedback chỉ sửa được những lỗi mà lẽ ra model đã có thể làm đúng dựa trên nguồn tài liệu. Các phương án A, B và C đều là những sai lệch về cấu trúc hoặc định dạng mà model có thể sửa được khi nhận phản hồi về shape hoặc format mong muốn, vì thông tin cơ sở đúng vẫn hiện diện trong tài liệu; còn thông tin ở phương án D thì đơn giản là không tồn tại trong những gì model có thể nhìn thấy.","o":{"A":"Model trích xuất từ khóa (keywords) dưới dạng một object lồng nhau được tổ chức theo danh mục trong khi schema yêu cầu một mảng phẳng (flat array) các chuỗi","B":"Model trích xuất số lượng trích dẫn (citation counts) dưới dạng chuỗi theo định dạng locale (\"1,234\") trong khi schema yêu cầu số nguyên (integer)","C":"Model trích xuất ngày tháng dưới dạng chuỗi datetime ISO 8601 (\"2023-03-15T00:00:00Z\") trong khi schema chỉ yêu cầu phần ngày (YYYY-MM-DD)","D":"Model trích xuất \"et al.\" cho các đồng tác giả trong khi danh sách đầy đủ chỉ tồn tại trong một tài liệu bên ngoài không có trong input"}},"67":{"q":"Pipeline extraction của bạn xử lý thực đơn nhà hàng và phải xuất ra JSON có cấu trúc với các field cho tên món, mô tả, giá, và dietary tags (nhãn chế độ ăn). Một số thực đơn dùng định dạng không nhất quán — giá được viết là \"$12\" so với \"12.00\", thông tin dietary dưới dạng icon so với văn bản. Đâu là cách tiếp cận đáng tin cậy nhất?","e":"Một schema chặt chẽ kết hợp với các quy tắc chuẩn hóa (normalization) rõ ràng (ví dụ: giá ở dạng số thập phân hai chữ số, dietary là các tag dạng enum) cho phép model vừa extract vừa chuẩn hóa trong một lượt. Gọi API riêng cho từng field (A) làm tăng gấp bội chi phí và latency, đồng thời mất đi ngữ cảnh liên trường (cross-field context); post-processing trên một khối dữ liệu thô (B) rất dễ vỡ vì code deterministic phải xử lý mọi hoán vị định dạng có thể có; còn ensemble voting (C) thì tốn kém và vẫn có thể chọn ra một kết quả đa số sai định dạng.","o":{"A":"Sử dụng các lệnh gọi trích xuất (extraction call) riêng biệt cho mỗi field để đảm bảo xử lý nhất quán cho từng loại.","B":"Trích xuất dữ liệu nguyên trạng (as-is) và chuẩn hóa định dạng trong code xử lý hậu kỳ (post-processing) sau khi Claude trả về.","C":"Yêu cầu nhiều lần thử trích xuất cho mỗi tài liệu và chọn định dạng phổ biến nhất.","D":"Định nghĩa một schema đầu ra nghiêm ngặt (strict output schema) và đưa các quy tắc chuẩn hóa định dạng vào prompt của bạn."}},"68":{"q":"Hệ thống của bạn trích xuất event metadata (date, location, organizer, attendee_count) từ các bài báo bằng một JSON schema mà tất cả các field đều nullable. Trong quá trình evaluation, bạn quan sát thấy model thường xuyên tạo ra các giá trị nghe có vẻ hợp lý nhưng không chính xác cho những field không được đề cập trong bài báo — ví dụ, xuất ra \"500\" cho attendee_count trong khi nguồn không hề chứa thông tin về số người tham dự. Đâu là cách hiệu quả nhất để giảm các extraction sai lệch (false extraction) này?","e":"Các field đã là nullable sẵn; model chỉ cần một chỉ thị rõ ràng để ưu tiên trả về null thay vì một phỏng đoán nghe có vẻ hợp lý. Đây là cách sửa tiêu chuẩn cho hiện tượng hallucination liên quan đến schema (schema-aware hallucination). Gọi thêm một lượt LLM thứ hai để verification (A) là một bước tốn kém cho một hành vi vốn có thể sửa ngay tại nguồn; buộc các field là required (C) ép model phải bịa ra giá trị khi thông tin bị thiếu — ngược lại hoàn toàn với mục tiêu; và nâng cấp lên model tier cao hơn (D) làm tăng chi phí mà không hề nói cho model biết chính sách thực sự cần tuân theo.","o":{"A":"Thêm một bước xử lý hậu kỳ (post-processing) sử dụng lệnh gọi LLM thứ hai để xác minh mỗi giá trị được trích xuất đều tồn tại trong tài liệu nguồn.","B":"Thêm hướng dẫn vào prompt để trả về null cho bất kỳ field nào mà thông tin không được nêu trực tiếp trong nguồn.","C":"Đặt tất cả các field trong schema thành bắt buộc (non-nullable) với các quy tắc xác thực nghiêm ngặt để đảm bảo model chỉ xuất ra dữ liệu có thể kiểm chứng.","D":"Nâng cấp lên một tier model mạnh hơn với khả năng tuân theo hướng dẫn (instruction-following) được cải thiện để giảm xu hướng hallucination."}},"69":{"q":"Sau khi triển khai tool use với các định nghĩa schema nghiêm ngặt, lỗi cú pháp JSON đã được loại bỏ hoàn toàn, nhưng 5% số extraction vẫn cho ra JSON hợp lệ với mảng rỗng hoặc giá trị null cho các field bắt buộc như citations và methodology. Kiểm tra ngẫu nhiên cho thấy tài liệu nguồn có chứa thông tin này, nhưng ở nhiều định dạng khác nhau — trích dẫn inline so với danh mục tài liệu tham khảo (bibliography), các mục methodology riêng biệt so với chi tiết được lồng trong phần giới thiệu (introduction). Đâu là cách hiệu quả nhất để giải quyết các lỗi này?","e":"Nguyên nhân gốc của lỗi là model không nhận diện được các định dạng khác nhau. Các ví dụ cụ thể trải rộng qua các dạng phân bố định dạng sẽ trực tiếp nâng recall cho phần 5% này. Retry với cùng một prompt (A) không dạy được cho model cách nhận ra methodology được lồng trong phần giới thiệu, dùng regex trên văn xuôi (B) rất dễ vỡ và có thể âm thầm cho ra dữ liệu sai, còn việc biến các field thành optional (C) chỉ che giấu triệu chứng bằng cách đẩy vấn đề sang khối lượng công việc của reviewer thay vì sửa tận gốc việc extraction.","o":{"A":"Triển khai logic thử lại (retry logic) để gửi lại request khi việc xác thực (validation) phát hiện các field bắt buộc bị rỗng.","B":"Xây dựng một lớp xử lý hậu kỳ dựa trên regex, quét các tài liệu nguồn để tìm các mẫu trích dẫn (citation) và từ khóa phương pháp luận (methodology), điền vào các field rỗng khi model không trích xuất được.","C":"Sửa đổi schema của bạn để làm cho citations và methodology trở thành tùy chọn (optional), và gắn cờ các bản ghi không đầy đủ để xem xét thủ công thay vì làm cho validation thất bại.","D":"Thêm các few-shot example minh họa việc trích xuất từ các tài liệu có cấu trúc đa dạng — cho thấy cách nhận diện citation ở các định dạng khác nhau và xác định vị trí chi tiết methodology trên các loại section khác nhau."}},"70":{"q":"Pipeline extraction của bạn xử lý hóa đơn và trích xuất line items (các mục hàng hóa/dịch vụ), subtotal, số tiền thuế, và grand total. Trong quá trình evaluation, bạn phát hiện rằng trong 18% số extraction, tổng của các line item amount được trích xuất không khớp với grand total được trích xuất — đôi khi do lỗi OCR trong tài liệu nguồn, đôi khi do lỗi extraction của model. Các hệ thống kế toán downstream từ chối các bản ghi có tổng số không khớp. Đâu là cách tiếp cận hiệu quả nhất để cải thiện độ tin cậy của extraction?","e":"Việc thu thập cả calculated_total lẫn stated_total biến sự chênh lệch (discrepancy) thành một tín hiệu chính thức (first-class signal) — bạn bắt được cả lỗi OCR lẫn lỗi extraction theo cùng một cách thống nhất, và chỉ cần định tuyến phần 18% không khớp đến con người. Một reconciliation model (B) có thể che giấu lỗi OCR bằng cách âm thầm chọn con số này thay vì con số kia, few-shot examples (C) không giúp được gì khi bản thân nguồn tài liệu đã tự mâu thuẫn nội tại, còn việc âm thầm ghi đè lại các line item amount (D) rất nguy hiểm vì nó bịa ra dữ liệu tài chính cho một hệ thống kế toán downstream.","o":{"A":"Thêm một field \"calculated_total\" trong đó model tính tổng các mục hàng (line item) đã trích xuất cùng với một field \"stated_total\". Gắn cờ các bản ghi để con người xem xét khi các giá trị khác nhau.","B":"Trích xuất các line item và tổng số một cách độc lập, sau đó sử dụng một model xác thực riêng để đối chiếu (reconcile) các sai lệch bằng cách xác định giá trị trích xuất nào có khả năng đúng nhất.","C":"Thêm các few-shot example minh họa các hóa đơn trong đó tổng các line item được trích xuất khớp chính xác với stated total, khuyến khích model đưa ra các kết quả trích xuất nhất quán về mặt toán học.","D":"Triển khai xử lý hậu kỳ tự động điều chỉnh tỷ lệ các số tiền line item khi tổng của chúng không khớp với stated total."}},"71":{"q":"Pipeline của bạn sử dụng một tool tên là extract_metadata với một JSON schema cho thông tin chi tiết của bài báo. Bạn cũng đã định nghĩa các tool lookup_citations và verify_doi để làm giàu dữ liệu (enrichment). Trong quá trình testing, bạn nhận thấy rằng khi người dùng đưa ra các yêu cầu như \"extract the metadata and tell me how cited it is\" (trích xuất metadata và cho tôi biết nó được trích dẫn bao nhiêu), Claude đôi khi gọi lookup_citations trước, và việc này thất bại vì nó cần đến DOI mà lẽ ra extract_metadata phải cung cấp. Đâu là cách hiệu quả nhất để đảm bảo việc trích xuất structured metadata diễn ra trước?","e":"Đặt tool_choice trỏ vào tool cụ thể sẽ buộc extract_metadata phải được gọi ở lượt đầu tiên một cách xác định (deterministic). Sau đó, quyền kiểm soát được trả lại về \"auto\" để model có thể dùng citations/DOI enrichment với metadata đã sẵn có trong context. \"any\" (A) buộc phải có một lệnh gọi tool nhưng không nhất thiết là đúng tool, không có tài liệu nào ghi nhận rằng thứ tự ưu tiên phụ thuộc vào vị trí trong mảng (array position) (B), và việc ghim (pin) extract_metadata ở mọi lệnh gọi (D) khiến các tool enrichment không bao giờ được sử dụng.","o":{"A":"Đặt tool_choice thành \"any\" để buộc Claude phải sử dụng một tool, kết hợp với hướng dẫn trong system prompt ưu tiên extract_metadata.","B":"Đặt tool_choice thành \"auto\" và sắp xếp lại thứ tự định nghĩa tool sao cho extract_metadata xuất hiện đầu tiên trong mảng tools, vì Claude ưu tiên các tool được liệt kê trước.","C":"Đặt tool_choice thành {\"type\": \"tool\", \"name\": \"extract_metadata\"} và xử lý các yêu cầu enrichment ở các lượt (turn) tiếp theo sau khi nhận được metadata đã trích xuất.","D":"Đặt tool_choice thành {\"type\": \"tool\", \"name\": \"extract_metadata\"} cho mọi lệnh gọi API trong pipeline, đảm bảo Claude luôn trích xuất metadata trước khi bất kỳ enrichment nào có thể diễn ra."}},"72":{"q":"Extraction của bạn sử dụng tool use với một JSON schema trong đó property_type được định nghĩa là một enum: ['house', 'apartment', 'condo', 'townhouse']. Sau khi triển khai, 8% số extraction thất bại validation schema. Điều tra cho thấy các tin đăng đề cập đến nhiều loại bất động sản không phổ biến — \"studio\", \"loft\", \"duplex\", \"mobile home\", \"tiny house\", \"converted warehouse\" — và các loại mới vẫn tiếp tục xuất hiện đều đặn. Đâu là giải pháp dài hạn hiệu quả nhất?","e":"Thêm một giá trị enum \"other\" kèm theo một field detail riêng vẫn giữ được enum chặt chẽ cho các trường hợp phổ biến (giúp các phép join downstream sạch sẽ), đồng thời cung cấp một lối thoát có kiểu (well-typed escape hatch) để bảo toàn chi tiết — ổn định về lâu dài. Liên tục mở rộng enum (A) giống như trò chơi đập chuột (whack-a-mole) trong việc bảo trì, chuyển sang string tự do (free-form string) (C) đánh mất hoàn toàn đảm bảo về validation và đẩy việc chuẩn hóa xuống downstream mà không có một bộ từ vựng chuẩn (canonical vocabulary) nào, còn việc ép các loại bất thường vào giá trị hiện có gần nhất (D) làm mất đi những khác biệt thật sự và âm thầm gây mất dữ liệu (lossy).","o":{"A":"Liên tục mở rộng enum để bao gồm các loại property mới được quan sát và thêm giám sát cho các trường hợp biên (edge case) bổ sung.","B":"Thêm một giá trị \"other\" vào enum của bạn cùng với một field string riêng property_type_detail để ghi chi tiết cụ thể khi \"other\" được chọn.","C":"Đổi property_type từ enum sang chuỗi tự do (free-form string) và triển khai một bước chuẩn hóa trong xử lý hậu kỳ.","D":"Thêm các few-shot example vào prompt của bạn minh họa cách ánh xạ các loại property không mong đợi tới giá trị enum hiện có gần nhất."}},"73":{"q":"Hệ thống extraction của bạn phân tích mô tả sản phẩm thương mại điện tử để trích xuất các thông số kỹ thuật như dimensions (kích thước), weight (trọng lượng), và materials (chất liệu) vào JSON. Mặc dù đã có một schema được định nghĩa rõ ràng, model vẫn trích xuất không nhất quán field \"materials\" — đôi khi trả về \"cotton blend\", đôi khi lại là \"Cotton/Polyester mix\", và thỉnh thoảng bỏ qua field này ngay cả khi thông tin về chất liệu rõ ràng có trong nguồn. Đâu là cách hiệu quả nhất để cải thiện tính nhất quán của extraction?","e":"Few-shot examples minh họa chính xác định dạng chuẩn (canonical format) mà bạn muốn (ví dụ: một danh sách \"cotton/polyester\" đã được chuẩn hóa), đồng thời cũng nâng recall đối với các thông tin về chất liệu vốn đang bị bỏ sót. Buộc field này là required (A) không giải quyết được sự thiếu nhất quán về định dạng và có thể ép model bịa ra giá trị, nâng cấp lên model tier cao hơn (B) tốn kém và không giải quyết đúng nguyên nhân, còn đặt temperature về 0 (C) chỉ khiến các câu trả lời sai định dạng trở nên nhất quán chứ không định nghĩa đúng định dạng cần có.","o":{"A":"Đặt field \"materials\" thành bắt buộc thay vì tùy chọn trong schema để buộc model luôn trích xuất một giá trị","B":"Chuyển sang một tier model mạnh hơn vì việc trích xuất không nhất quán cho thấy năng lực model chưa đủ","C":"Đặt temperature về 0 để loại bỏ tính ngẫu nhiên và đảm bảo đầu ra tất định (deterministic)","D":"Thêm các few-shot example thể hiện 2-3 cặp input-output hoàn chỉnh với định dạng mô tả vật liệu (material description) được chuẩn hóa"}},"74":{"q":"Sau khi triển khai, bạn phát hiện rằng 12% số extraction chứa lỗi ngữ nghĩa (semantic error) nhưng vẫn vượt qua được validation của JSON schema (ví dụ: một khoảng thời gian như \"30 minutes\" bị đặt nhầm vào một field số lượng nguyên liệu). Các reviewer con người chỉ có khả năng kiểm tra được 20% số extraction. Cách tiếp cận nào phân bổ sự chú ý của reviewer hiệu quả nhất?","e":"Confidence ở cấp field cho phép bạn định tuyến phần 20% có confidence thấp — nơi tập trung phần lớn 12% lỗi ngữ nghĩa — đến con người, và việc calibration giúp việc chọn ngưỡng (threshold) dựa trên dữ liệu thực tế. Random sampling (B) tốt cho việc đo lường nhưng kém về độ bao phủ, chỉ bắt được một phần nhỏ trong số các lỗi thực tế. Việc review các field rỗng (C) bỏ sót vấn đề 12% về các giá trị sai trong những field đã được điền, còn việc review các bất thường về định dạng (D) không dự đoán một cách đáng tin cậy nơi các field bị nhầm lẫn với nhau.","o":{"A":"Cho model xuất ra điểm confidence ở cấp độ field, sau đó hiệu chỉnh (calibrate) các ngưỡng xem xét bằng một tập validation đã được gán nhãn.","B":"Lấy mẫu ngẫu nhiên 20% các trích xuất để xem xét, sử dụng các chỉnh sửa để theo dõi độ chính xác và xác định các mẫu lỗi.","C":"Ưu tiên xem xét tất cả các trích xuất mà các field bắt buộc bị rỗng hoặc được đánh dấu rõ ràng là không tìm thấy.","D":"Xem xét tất cả các trích xuất từ những tài liệu có bất thường về định dạng, chẳng hạn như bố cục khác thường hoặc loại nội dung hỗn hợp."}},"75":{"q":"Pipeline CI của bạn thực hiện các code review tập trung vào bảo mật (security-focused) trên khoảng 50 PR mỗi ngày, hiện đang tốn $150/ngày khi dùng synchronous API. Các review này là non-blocking — developer merge sau khi test pass và xử lý các finding trong các commit tiếp theo. Bạn đang cân nhắc dùng Message Batches API vì mức giảm chi phí 50%. Yếu tố nào quyết định nhiều nhất việc xử lý batch có phù hợp với use case này hay không?","e":"Message Batches API là bất đồng bộ (asynchronous) — hầu hết các batch hoàn tất trong vòng 1 giờ nhưng có thể mất đến 24 giờ — vì vậy yếu tố quyết định về mức độ phù hợp chính là khả năng chịu đựng latency (latency tolerance): liệu các finding của review được trả về sau tối đa 24 giờ kể từ khi tạo PR có còn hữu ích để hành động trong một quy trình non-blocking, merge-rồi-mới-sửa hay không. Batching làm tăng latency chứ không giảm (B nói ngược); kết quả được liên kết (correlate) thông qua custom_id nên thứ tự không phải là vấn đề (D); và việc cấu trúc thành từng single request (A) là vấn đề thứ yếu so với câu hỏi về latency.","o":{"A":"Liệu bạn có thể cấu trúc mỗi lần review thành một request duy nhất mà không cần tinh chỉnh qua nhiều lượt (multi-turn refinement) hay không.","B":"Liệu việc giảm độ trễ mỗi lần review từ 30-60 giây xuống gần như tức thời có quan trọng đối với quy trình làm việc của bạn hay không.","C":"Liệu phản hồi review đến sau tối đa 24 giờ kể từ khi tạo PR có còn khả thi để hành động hay không.","D":"Liệu quá trình xử lý kết quả của bạn có thể xử lý các review đến theo thứ tự khác với thứ tự đã gửi hay không."}},"76":{"q":"Tài liệu liên tục đến trong suốt giờ làm việc và cần được trích xuất dữ liệu có cấu trúc. Để giảm chi phí, bạn muốn dùng Message Batches API (giảm giá 50%, cửa sổ xử lý lên đến 24 giờ). SLA của bạn quy định rằng kết quả extraction phải sẵn có trong vòng 30 giờ kể từ khi tài liệu đến, với độ tin cậy 99.9%. Chiến lược batching nào là phù hợp nhất?","e":"Thời gian chờ tối đa 4 giờ cộng với SLO xử lý batch lên đến 24 giờ cho ra kịch bản xấu nhất là 28 giờ, để lại một khoảng đệm 2 giờ so với SLA 30 giờ nhằm hấp thụ sự biến động của batch và đạt được 99.9%. Gửi batch mỗi 6 giờ (A) cho ra kịch bản xấu nhất đúng bằng 30 giờ, không có biên độ an toàn nào; một batch duy nhất vào cuối ngày (B) có thể khiến một tài liệu đến sớm phải chờ vượt xa mốc 30 giờ; và việc dùng real-time API cho tất cả (D) đáp ứng SLA một cách hiển nhiên nhưng lại từ bỏ khoản tiết kiệm chi phí 50% mà câu hỏi yêu cầu bạn phải đạt được.","o":{"A":"Gửi các batch mỗi 6 giờ chứa các tài liệu trong khung thời gian đó","B":"Gửi một batch duy nhất vào cuối ngày chứa tất cả tài liệu của ngày hôm đó","C":"Gửi các batch mỗi 4 giờ chứa các tài liệu trong khung thời gian đó","D":"Sử dụng real-time API cho tất cả tài liệu thay vì xử lý theo batch"}},"77":{"q":"Sau khi batch hàng ngày gồm 10.000 tài liệu của bạn hoàn tất, 300 tài liệu (3%) thất bại với lỗi \"context_length_exceeded\". File kết quả xác định từng lỗi bằng custom_id. Đâu là cách tiếp cận tiết kiệm chi phí nhất để xử lý các lỗi này?","e":"Đây là cách tiếp cận có mục tiêu (targeted), và nó giải quyết đúng nguyên nhân thực sự (input quá dài): chia nhỏ (chunk) các tài liệu quá khổ, extract theo từng chunk, rồi merge lại — tốn ít token nhất và sửa đúng mẫu lỗi cụ thể này. Xử lý lại toàn bộ batch với caching (A) chạy lại cả 10.000 tài liệu đã thành công chỉ để sửa 300 lỗi, hơn nữa caching cũng không sửa được lỗi vượt quá độ dài (length-exceeded) dù thế nào; xử lý lại toàn bộ với một model có context lớn hơn (C) tốn kém và vẫn có thể thất bại với những tài liệu thực sự quá khổ; còn tăng max_tokens (D) chỉ kiểm soát độ dài output chứ không phải độ dài input, nên hoàn toàn không giải quyết được context_length_exceeded.","o":{"A":"Xử lý lại toàn bộ batch với prompt caching được bật để giảm chi phí thử lại các request có system prompt giống hệt nhau","B":"Chỉ gửi lại 300 tài liệu bị lỗi sau khi chia nhỏ (chunking) chúng thành các phần nhỏ hơn, sau đó kết hợp các kết quả trích xuất từng phần","C":"Gửi lại toàn bộ batch 10.000 tài liệu bằng một tier model có context window lớn hơn","D":"Tăng tham số max_tokens cho 300 tài liệu bị lỗi và gửi lại chúng trong một batch mới"}}};
